// Nodo Code: «Separar subtemas en la tabla2» · Modo: Run Once for All Items
// En la plantilla la celda «Subtemas» viene combinada de dos en dos (OVI 1 + OVA 1, OVI 2 + OVA 2
// y OVI 3 + OVA 3), que es lo correcto cuando el tema tiene 3 subtemas. Con 4 o más subtemas
// el OVA aborda un subtema propio: aquí se descombina esa celda y se escribe en ella su
// marcador <<Rec_OVA_N_TT>>, que luego llena replaceAllText.
// Si la tabla no tiene la forma esperada, el subtema del OVA se escribe en la celda
// combinada, debajo del subtema del OVI (respaldo), para que nunca se pierda.

const SIN_CAMBIOS = { replaceAllText: { containsText: { text: '<<__sin_cambios__>>', matchCase: true }, replaceText: '' } };
const textoParrafo = el => (el.paragraph?.elements || []).map(e => e.textRun?.content || '').join('');
const textoCelda = c => (c?.content || []).map(textoParrafo).join('');

return $input.all().map((item, i) => {
  const base = $('Conservar unidad y copia5').all()[i].json;
  const marcadores = base.marcadores || {};
  const tablas = (item.json.body?.content || []).filter(el => el.table);
  const descombinar = [];
  const inserciones = [];
  const respaldo = {};
  const separados = [];
  const advertencias = [];

  for (let t = 1; t <= 4; t++) {
    for (const k of [1, 2, 3]) {
      const marcadorOva = '<<Rec_OVA_' + k + '_T' + t + '>>';
      const marcadorOvi = '<<Rec_OVI_' + k + '_T' + t + '>>';
      if (!String(marcadores[marcadorOva] || '').trim()) continue; // comparte subtema con el OVI

      let ubicado = null;
      for (const el of tablas) {
        const filas = el.table.tableRows || [];
        const r = filas.findIndex(f => (f.tableCells || []).some(c => textoCelda(c).includes('<<Nom_OVA_' + k + '_T' + t + '>>')));
        if (r > 0) { ubicado = { el, filas, r }; break; }
      }
      const celdaOva = ubicado && ubicado.filas[ubicado.r].tableCells[0];
      const celdaOvi = ubicado && ubicado.filas[ubicado.r - 1].tableCells[0];
      const formaEsperada = celdaOva && celdaOvi &&
        textoCelda(celdaOvi).includes(marcadorOvi) && !textoCelda(celdaOva).includes('<<Nom_') &&
        celdaOva.content && celdaOva.content[0] && Number.isInteger(celdaOva.content[0].startIndex);

      if (!formaEsperada) {
        respaldo[marcadorOvi] = [marcadores[marcadorOvi], marcadores[marcadorOva]].filter(Boolean).join('\n');
        advertencias.push('Tema ' + t + ': no se pudo separar la celda de subtemas de OVI ' + k + ' y OVA ' + k + '; ambos subtemas quedan en la misma celda.');
        continue;
      }
      if (textoCelda(celdaOva).includes(marcadorOva)) continue; // la plantilla ya trae la celda separada
      if ((celdaOvi.tableCellStyle?.rowSpan || 1) > 1) {
        descombinar.push({
          unmergeTableCells: {
            tableRange: {
              tableCellLocation: { tableStartLocation: { index: ubicado.el.startIndex }, rowIndex: ubicado.r - 1, columnIndex: 0 },
              rowSpan: 2,
              columnSpan: 1
            }
          }
        });
      }
      inserciones.push({ insertText: { location: { index: celdaOva.content[0].startIndex }, text: marcadorOva } });
      separados.push([marcadorOvi, marcadorOva]);
    }
  }

  // Descombinar no mueve el texto; las inserciones van de la última a la primera
  // para que los índices calculados sigan siendo válidos.
  inserciones.sort((a, b) => b.insertText.location.index - a.insertText.location.index);
  const estructura = [...descombinar, ...inserciones];

  // Respaldo: el subtema del OVA va en la celda combinada, debajo del del OVI.
  const conRespaldo = tabla => (base.replace_requests || []).map(r => {
    const m = r.replaceAllText?.containsText?.text;
    return m in tabla ? { replaceAllText: { ...r.replaceAllText, replaceText: tabla[m] } } : r;
  });
  // Por si Google Docs rechaza la separación: todos los pares quedan en su celda combinada.
  const respaldoTotal = { ...respaldo };
  for (const [ovi, ova] of separados) respaldoTotal[ovi] = [marcadores[ovi], marcadores[ova]].filter(Boolean).join('\n');

  return {
    json: {
      ...base,
      estructura_requests: estructura.length ? estructura : [SIN_CAMBIOS],
      replace_requests: conRespaldo(respaldo),
      replace_requests_respaldo: conRespaldo(respaldoTotal),
      advertencias: [...(base.advertencias || []), ...advertencias]
    },
    pairedItem: { item: i }
  };
});

// Nodo Code: «Elegir reemplazos2» · Modo: Run Once for All Items
// Si Google Docs aceptó la separación de celdas se usan los reemplazos normales; si la
// rechazó, los de respaldo (el subtema del OVA queda en la celda combinada del OVI).
return $input.all().map((item, i) => {
  const base = $('Separar subtemas en la tabla').all()[i].json;
  const fallo = item.json && item.json.error;
  return {
    json: {
      ...base,
      replace_requests: fallo ? base.replace_requests_respaldo : base.replace_requests,
      advertencias: fallo
        ? [...(base.advertencias || []), 'Google Docs no permitió separar las celdas de subtemas; los subtemas adicionales quedan en la celda combinada.']
        : base.advertencias
    },
    pairedItem: { item: i }
  };
});

// Prepara una copia por unidad y un replaceAllText por cada marcador del mapa.
const plantilla = $('Resolver plantilla5').first().json;
const plantillaId = plantilla.plantilla_id;
if (!plantillaId) throw new Error('No se pudo resolver el ID de la plantilla de Google Docs.');
const limpiarNombre = (s) => String(s || '').replace(/[\\/:*?"<>|#%{}~&]/g, ' ').replace(/\s+/g, ' ').trim();
return $input.all().map((item, index) => {
  const j = item.json;
  const marcadorMap = j.marcadores || {};
  const requests = Object.entries(marcadorMap).map(([marcador, valor]) => ({
    replaceAllText: {
      containsText: { text: marcador, matchCase: true },
      replaceText: String(valor ?? '')
    }
  }));
  if (!requests.length) throw new Error('La unidad ' + (j.unidad || '?') + ' no tiene marcadores para rellenar.');
  const titulo = limpiarNombre('Syllabus - ' + (j.asignatura || 'Asignatura') + ' - Unidad ' + (j.unidad || '') + ' - ' + (j.nombre_unidad || ''));
  return { json: { ...j, plantilla_file_id: plantillaId, nombre_copia: titulo.slice(0, 180), replace_requests: requests }, pairedItem: { item: index } };
});

// Conserva el contenido de la unidad y agrega los datos de la copia que devolvió Drive.
const unidad = $('Preparar copia por unidad5').item.json;
const copia = $input.item.json;
if (!copia.id) throw new Error('Google Drive no devolvió el ID de la copia.');
const url = copia.webViewLink || ('https://docs.google.com/document/d/' + copia.id + '/edit');
return { json: { ...unidad, documento_generado: { id: copia.id, nombre: copia.name || unidad.nombre_copia, url } } };

// NODO: «Preparar respuesta con enlace»  ·  Modo: "Run Once for All Items"
// Se ejecuta UNA sola vez con todas las unidades y devuelve UN solo ítem con los enlaces de los documentos.
// Ese ítem es el que debe enviar el nodo «Responder enlaces de plantillas» al portal / plataforma.

const salidas = $input.all();
const documentos = salidas.map((salida, i) => {
  const actualizacion = salida.json || {};
  if (actualizacion.error) {
    throw new Error('No se pudo rellenar la copia de Google Docs: ' + actualizacion.error);
  }

  // Datos de la unidad y de la copia que conservó el nodo anterior (mismo orden de ítems).
  let unidad;
  try { unidad = $('Conservar unidad y copia5').itemMatching(i).json; }
  catch (e) { unidad = $('Conservar unidad y copia5').all()[i].json; }

  const copia = unidad.documento_generado || {};
  const numero =
    (unidad.unidad && unidad.unidad.numero) ??
    unidad.numero_unidad ??
    (typeof unidad.unidad === 'number' || typeof unidad.unidad === 'string' ? unidad.unidad : undefined) ??
    (i + 1);
  const url = copia.url || (copia.id ? 'https://docs.google.com/document/d/' + copia.id + '/edit' : '');

  return {
    unidad: { numero: Number(numero) || i + 1 },
    nombre_unidad: unidad.nombre_unidad || copia.nombre || ('Unidad ' + (i + 1)),
    url,
    documento_generado: {
      id: copia.id || '',
      nombre: copia.nombre || unidad.nombre_copia || unidad.nombre_unidad || '',
      url,
      diligenciado: true
    }
  };
});

return [{
  json: {
    ok: true,
    total: documentos.length,
    documentos_generados: documentos
  }
}];

// Nodo Code: "Identificar Google Doc"
// Se ejecuta solo cuando la petición NO trae archivo. Espera un JSON con
// { "syllabus_url": "https://docs.google.com/document/d/<ID>/edit..." } y
// construye la URL de exportación a .docx.
//
// El documento debe estar compartido como "Cualquier persona con el enlace
// puede ver". Si es privado, Google devuelve una página de inicio de sesión y
// el nodo siguiente fallará: en ese caso hay que enviar el archivo directamente.

const entrada = $input.first().json;
const cuerpo = entrada.body || {};
const url = String(cuerpo.syllabus_url || cuerpo.url || 'https://docs.google.com/document/d/1vU_DCZxv-0eW4wRFk7EqQ_iFStfQm8WPyr-vLdfqcK4/edit?usp=sharing').trim();

if (!url) {
  throw new Error(
    'No llegó ni archivo ni enlace. Envía el .docx en el campo "data" o un JSON con "syllabus_url".'
  );
}

const m = /docs\.google\.com\/document\/d\/([A-Za-z0-9_-]+)/.exec(url);
if (!m) {
  throw new Error(
    'El enlace no es un Google Doc ("docs.google.com/document/d/<ID>"). Recibido: ' + url
  );
}

return [
  {
    json: {
      origen: { tipo: 'google_docs', url, file_id: m[1] },
      export_url: 'https://docs.google.com/document/d/' + m[1] + '/export?format=docx'
    }
  }
];

// Nodo Code: "Preparar DOCX"
// Recibe el .docx (subido en el campo "data" o descargado de Google Docs) y lo
// presenta como ZIP para que el nodo Compression pueda abrirlo. Un .docx es
// internamente un ZIP: aquí solo se cambian metadatos, nunca el contenido.
// También deja registrado de dónde vino el documento.

const item = $input.first();

if (!item.binary || !item.binary.data) {
  throw new Error('No se recibió ningún archivo. Envía el Syllabus .docx en el campo "data".');
}

// El origen solo existe cuando el documento llegó por enlace.
let origen = { tipo: 'archivo', url: null, file_id: null };
try {
  origen = { ...origen, ...$('Identificar Google Doc5').first().json.origen };
} catch (e) {
  // Subida directa: el nodo de enlaces no se ejecutó.
}

const nombre = item.binary.data.fileName || 'syllabus.docx';
const bytes = item.binary.data.fileSize;

// Un .docx es un ZIP y empieza por "PK". Si Google devolvió una página de inicio
// de sesión (documento privado), se detecta aquí y no más adelante con un error
// confuso.
const cabecera = Buffer.from(await this.helpers.getBinaryDataBuffer(0, 'data')).slice(0, 2).toString('latin1');
if (cabecera !== 'PK') {
  throw new Error(
    origen.tipo === 'google_docs'
      ? 'Google no devolvió un .docx: el documento probablemente no está compartido con "Cualquier persona con el enlace". Compártelo o envía el archivo directamente.'
      : 'El archivo recibido no es un .docx válido.'
  );
}

item.binary.data.fileName = 'syllabus.zip';
item.binary.data.fileExtension = 'zip';
item.binary.data.mimeType = 'application/zip';

item.json = {
  ...item.json,
  original_file_name: nombre,
  tamano_bytes: bytes || null,
  origen
};

return [item];

// Nodo Code: "Extraer Syllabus"
// Lee word/document.xml del DOCX descomprimido y lo convierte en un JSON
// estructurado del Syllabus. Todo lo que sale de aquí es dato literal del
// documento: no se inventa ni se reformula nada.
//
// Cada referencia bibliográfica recibe un ID estable (U1-B1, U1-C2…) que el
// resto del flujo usa para registrar de dónde sale cada contenido.

// ---------- utilidades XML ----------

function unescapeXml(s) {
  return s
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&');
}

// OJO: <w:t[^>]*> también casaría con <w:tc>. Hay que exigir espacio o cierre.
function textOf(xml) {
  const re = /<w:t(?: [^>]*)?>([\s\S]*?)<\/w:t>/g;
  let out = '';
  let m;
  while ((m = re.exec(xml))) out += m[1];
  return unescapeXml(out).replace(/\s+/g, ' ').trim();
}

// Devuelve los hijos <tag>...</tag> de primer nivel dentro de xml.
function splitTags(xml, tag) {
  const re = new RegExp('<' + tag + '([ >/])|</' + tag + '>', 'g');
  const out = [];
  let m, lvl = 0, start = 0;
  while ((m = re.exec(xml))) {
    if (m[0][1] === '/') {
      lvl--;
      if (lvl === 0) out.push([start, re.lastIndex]);
      continue;
    }
    const end = xml.indexOf('>', m.index) + 1;
    if (xml[end - 2] === '/') {
      if (lvl === 0) out.push([m.index, end]);
      re.lastIndex = end;
      continue;
    }
    if (lvl === 0) start = m.index;
    lvl++;
    re.lastIndex = end;
  }
  return out.map(([a, b]) => xml.slice(a, b));
}

// Texto de una celda conservando los párrafos (separados por \n). Así la
// bibliografía se puede cortar por párrafo cuando el autor la escribió así.
function textoCelda(xml) {
  return splitTags(xml, 'w:p').map(textOf).filter(Boolean).join('\n');
}

const aplanar = s => String(s || '').replace(/\s*\n\s*/g, ' ').replace(/\s+/g, ' ').trim();

// ---------- normalización de etiquetas ----------

function norm(s) {
  return String(s || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

// ---------- bibliografía ----------

const TIENE_ANIO = /\(\d{4}[a-z]?\)/;

// Corta un bloque de referencias en entradas individuales.
// 1) Si cada referencia está en su propio párrafo, se usa esa separación.
// 2) Si no, se corta justo antes del bloque de autoría que precede a cada "(AÑO)."
function splitRefs(blob) {
  const bruto = String(blob || '').trim();
  if (!bruto) return [];

  // Párrafos: se une al anterior todo párrafo que no traiga año (p. ej. una URL
  // que quedó en línea aparte).
  const lineas = bruto.split('\n').map(l => l.replace(/\s+/g, ' ').trim()).filter(Boolean);
  if (lineas.length > 1) {
    const unidas = [];
    for (const l of lineas) {
      if (unidas.length && !TIENE_ANIO.test(l)) unidas[unidas.length - 1] += ' ' + l;
      else unidas.push(l);
    }
    if (unidas.every(l => TIENE_ANIO.test(l))) return unidas;
  }

  const s = aplanar(bruto);
  const MAY = 'A-ZÁÉÍÓÚÑÜ';
  const PAL = "A-Za-zÁ-ÿ'’\\-";
  // Inicio de referencia: autor APA ("Apellido, X.") o entidad ("CAST. (2024)").
  const reInicio = new RegExp(
    '[' + MAY + '][' + PAL + ']*(?:\\s+[' + MAY + '][' + PAL + ']*)*,\\s+[' + MAY + ']\\.' +
      '|[' + MAY + '][^.]{0,80}\\.\\s*\\(\\d{4}',
    'g'
  );
  const inicios = [];
  let m;
  while ((m = reInicio.exec(s))) inicios.push(m.index);

  const anios = [];
  const reAnio = /\(\d{4}[a-z]?\)\./g;
  while ((m = reAnio.exec(s))) anios.push(m.index);

  // Para cada año, la referencia arranca en el primer inicio posterior al año
  // anterior: así se descartan los apellidos de los coautores.
  const cortes = [];
  let desde = -1;
  for (const anio of anios) {
    const corte = inicios.find(i => i > desde && i < anio);
    if (corte !== undefined && (cortes.length === 0 || corte > cortes[cortes.length - 1])) {
      cortes.push(corte);
    }
    desde = anio;
  }

  if (cortes.length === 0) return [s];
  const entradas = cortes.map((ini, k) => s.slice(ini, cortes[k + 1]).trim()).filter(Boolean);
  // Si algo quedó antes del primer corte, se antepone para no perder texto.
  if (cortes[0] > 0) {
    const cabeza = s.slice(0, cortes[0]).trim();
    if (cabeza) entradas.unshift(cabeza);
  }
  return entradas;
}

const limpiarFin = x => (x ? x.replace(/[.,;)\]]+$/, '') : null);

function entradaBibliografica(texto, id, tipo) {
  const doi = (texto.match(/10\.\d{4,9}\/[^\s"<>]+/) || [])[0] || null;
  const url = (texto.match(/https?:\/\/[^\s"<>]+/) || [])[0] || null;
  const anio = (texto.match(/\((\d{4})[a-z]?\)/) || [])[1] || null;
  return {
    id,
    tipo,
    texto,
    anio: anio ? Number(anio) : null,
    doi: limpiarFin(doi),
    url: limpiarFin(url)
  };
}

// ---------- entrada ----------

const item = $input.first();
const binarios = item.binary || {};
const claves = Object.keys(binarios);

// El nodo Compression nombra las salidas file_0, file_1, … y guarda la ruta
// original en fileName/directory, así que se busca por ambas vías.
const ruta = k => [binarios[k].directory, binarios[k].fileName, k].filter(Boolean).join('/');
const clave =
  claves.find(k => /word[\/\\]document\.xml$/i.test(ruta(k))) ||
  claves.find(k => /document\.xml$/i.test(binarios[k].fileName || k));

if (!clave) {
  throw new Error(
    'No se encontró word/document.xml en el archivo. ¿El .docx se descomprimió correctamente?'
  );
}

const buffer = await this.helpers.getBinaryDataBuffer(0, clave);
const xml = buffer.toString('utf8');

const body = xml.slice(xml.indexOf('<w:body>'));
const tablas = splitTags(body, 'w:tbl').map(t =>
  splitTags(t, 'w:tr').map(r => splitTags(r, 'w:tc').map(textoCelda))
);

// ---------- información general ----------

function buscarEtiqueta(...etiquetas) {
  const objetivo = etiquetas.map(norm);
  for (const filas of tablas) {
    for (const celdas of filas) {
      for (let i = 0; i < celdas.length - 1; i++) {
        if (objetivo.includes(norm(celdas[i]))) {
          const v = aplanar(celdas[i + 1]);
          if (v) return v;
        }
      }
    }
  }
  return null;
}

const horasFila = (() => {
  for (const filas of tablas) {
    for (const celdas of filas) {
      if (norm(celdas[0]) === 'horas' && celdas.length >= 6) return celdas.map(aplanar);
    }
  }
  return null;
})();

const general = {
  facultad: buscarEtiqueta('Facultad'),
  programa: buscarEtiqueta('Programa'),
  fecha_actualizacion: buscarEtiqueta('Fecha actualización'),
  asignatura: buscarEtiqueta('Denominación'),
  semestre: buscarEtiqueta('Semestre / periodo', 'Semestre'),
  creditos: buscarEtiqueta('Nro. de Créditos', 'Número de créditos'),
  prerrequisitos: buscarEtiqueta('Prerrequisitos'),
  nivel_formacion: buscarEtiqueta('Nivel de formación'),
  tipologia: buscarEtiqueta('Tipología de la asignatura'),
  modalidad: buscarEtiqueta('Modalidad'),
  horas_totales: horasFila ? horasFila[1] : null,
  horas_trabajo_directo: horasFila ? horasFila[3] : null,
  horas_trabajo_independiente: horasFila ? horasFila[5] : null,
  objetivo_programa: buscarEtiqueta('Objetivo del programa'),
  competencias_programa: buscarEtiqueta('Competencias del programa'),
  justificacion: buscarEtiqueta('Justificación de la asignatura')
};

const raAsignaturaRaw = buscarEtiqueta('Resultados de aprendizaje de la asignatura');
const resultados_aprendizaje = String(raAsignaturaRaw || '')
  .split(/(?=\d+\.\s)/g)
  .map(x => x.trim())
  .filter(Boolean);

// ---------- unidades ----------

const unidades = [];

// Cada unidad empieza en la fila cuya primera celda dice "Unidad Nro. N" (o "Unidad N°", "Unidad No.").
// Word une en una sola tabla las tablas que quedan pegadas, así que se corta por esas filas y no por tabla.
const RE_UNIDAD = /^Unidad\s*(?:Nro\.?|N[°ºo]\.?|N[uú]mero)\s*(\d+)|^Unidad\s+(\d+)\s*$/i;
const tablasUnidad = [];
for (const filas of tablas) {
  let enCurso = null;
  for (const fila of filas) {
    if (RE_UNIDAD.test(aplanar(fila[0]))) tablasUnidad.push(enCurso = [fila]);
    else if (enCurso) enCurso.push(fila);
  }
}

for (const filas of tablasUnidad) {
  const m = RE_UNIDAD.exec(aplanar(filas[0][0]));
  const numero = Number(m[1] || m[2]);
  if (unidades.some(u => u.numero === numero)) continue;
  const nombre = aplanar(filas[0][1]);
  const horas = aplanar(filas[0][3]);

  const filaInd = filas.find(c => norm(c[0]).startsWith('indicadores de logro'));
  const indicadoresRaw = filaInd ? aplanar(filaInd[1]) : '';
  const indicadores = indicadoresRaw
    .split(/(?=Indicador de Logro\s*\d+\s*:)/gi)
    .map(x => x.trim())
    .filter(Boolean);

  const iCabecera = filas.findIndex(
    c => norm(c[0]) === 'temas' && norm(c[1]) === 'subtemas'
  );
  const iBiblio = filas.findIndex(c => norm(c[0]).startsWith('bibliografia'));
  const fin = iBiblio === -1 ? filas.length : iBiblio;

  const temas = [];
  let actual = null;
  let estrategias_ensenanza = '';
  let estrategias_evaluativas = '';

  for (let i = iCabecera + 1; i < fin; i++) {
    const c = filas[i];
    if (!c) continue;
    if (norm(c[2]) === 'ad' && norm(c[3]) === 'ei') continue; // subcabecera AD/EI
    const subtema = aplanar(c[1]);
    if (!subtema) continue;

    const nombreTema = aplanar(c[0]);
    if (nombreTema || !actual) {
      actual = { nombre: nombreTema, subtemas: [] };
      temas.push(actual);
    }
    actual.subtemas.push({
      nombre: subtema,
      horas_trabajo_directo: aplanar(c[2]),
      horas_trabajo_independiente: aplanar(c[3])
    });
    if (!estrategias_ensenanza && (c[4] || '').trim()) estrategias_ensenanza = c[4].trim();
    if (!estrategias_evaluativas && (c[5] || '').trim()) estrategias_evaluativas = c[5].trim();
  }

  function bibliografiaTras(prefijo, letra) {
    const i = filas.findIndex(c => norm(c[0]).startsWith(norm(prefijo)));
    if (i === -1) return { raw: '', entradas: [] };
    // El texto puede estar en la misma fila (segunda celda) o en la siguiente.
    const raw = ((filas[i][1] || '').trim() || (filas[i + 1] ? (filas[i + 1][0] || '').trim() : ''));
    const entradas = splitRefs(raw).map((t, k) =>
      entradaBibliografica(t, 'U' + numero + '-' + letra + (k + 1), letra === 'B' ? 'basica' : 'complementaria')
    );
    return { raw: aplanar(raw), entradas };
  }

  unidades.push({
    numero,
    nombre,
    horas_estimadas: horas,
    indicadores_logro: indicadores,
    indicadores_logro_raw: indicadoresRaw,
    temas,
    estrategias_ensenanza,
    estrategias_evaluativas,
    bibliografia: {
      basica: bibliografiaTras('Bibliografía básica', 'B'),
      complementaria: bibliografiaTras('Bibliografía complementaria', 'C')
    }
  });
}

if (unidades.length === 0) {
  throw new Error(
    'No se encontró ninguna unidad ("Unidad Nro. N") en el documento. ' +
      '¿Es un Syllabus con el formato esperado?'
  );
}

// ---------- unidad solicitada ----------
// ?unidad=2 en el webhook procesa solo esa unidad; sin el parámetro, todas.
const consulta = ($('Webhook Syllabus3').first().json.query) || {};
const pedida = consulta.unidad ? Number(consulta.unidad) : null;
const seleccionadas = pedida ? unidades.filter(u => u.numero === pedida) : unidades;

if (seleccionadas.length === 0) {
  throw new Error(
    'El documento no tiene una Unidad Nro. ' + pedida + '. Unidades disponibles: ' +
      unidades.map(u => u.numero).join(', ')
  );
}

const origen = $('Preparar DOCX5').first().json.origen || { tipo: 'archivo', url: null };

// Lo que recibe el modelo: solo lo necesario, con la bibliografía ya numerada.
return seleccionadas.map(unidad => ({
  json: {
    archivo: $('Preparar DOCX5').first().json.original_file_name || null,
    origen,
    general,
    resultados_aprendizaje,
    unidad,
    total_unidades: unidades.length
  }
}));

// Nodo Code: "Armar salida"
// Combina lo extraído del Syllabus (dato literal) con lo generado por el modelo
// y produce los marcadores de la plantilla, la bibliografía de la unidad y el
// REGISTRO DE FUENTES: para cada marcador, si sale del Syllabus o fue generado,
// dónde está en el Syllabus y en qué referencias se apoya.
//
// Garantías que se verifican aquí, no en el modelo:
//  - Solo se aceptan IDs de bibliografía que existan en la unidad. Los demás se
//    descartan y quedan como advertencia.
//  - Donde el Syllabus ya tiene el dato, manda el Syllabus.
//  - El resultado de aprendizaje debe coincidir con uno del Syllabus.

const extraidos = $('Asignar actividades autoaprendizaje5').all();
const generados = $input.all();

const norm = s =>
  String(s || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

// Nombres cortos para celdas: sin comillas ni punto final, espacios simples y mayúscula inicial.
const limpiarNombre = s => {
  const t = String(s || '').replace(/["“”«»]/g, '').replace(/\s+/g, ' ').trim().replace(/[.;:,]+$/, '').trim();
  return t ? t.charAt(0).toLocaleUpperCase('es') + t.slice(1) : '';
};
// "1.Fundamentos", "Fundamentos" o "1 - Fundamentos" -> "1. Fundamentos".
const temaNumerado = (nombre, n) =>
  n + '. ' + limpiarNombre(String(nombre || '').replace(/^\s*\d+\s*[.)\-–]?\s*/, ''));

const NIVEL_VERIFICACION =
  'Vinculación por título y tema. El modelo no leyó el contenido de las obras: ' +
  'una persona debe validar que cada fuente realmente sustenta el recurso.';

const salida = generados.map((item, indice) => {
  const base = extraidos[indice] ? extraidos[indice].json : extraidos[0].json;
  const ia = item.json.output || item.json;

  const general = base.general;
  const unidad = base.unidad;
  const N = unidad.numero;
  const advertencias = [];


  // CONTROL DURO DE FORMATOS: los tres tipos de video cuentan como UNO.
  const formatosAsignados = (unidad.temas || []).flatMap(tema =>
    Object.values(tema.recursos_red_asignados || {}).map(x => String(x && x.red || ''))
  );
  const videosAsignados = formatosAsignados.filter(f => /^videos?\s/i.test(f));
  const podcastsAsignados = formatosAsignados.filter(f => /podcast/i.test(f));
  if (videosAsignados.length > 1) {
    throw new Error('UNIDAD ' + N + ': el maximo es UN VIDEO sumando academico, explicativo y micro-learning. Se encontraron: ' + videosAsignados.join(', '));
  }
  if (podcastsAsignados.length > 1) {
    throw new Error('UNIDAD ' + N + ': maximo un podcast para garantizar variedad de recursos.');
  }
  (unidad.temas || []).forEach((t, idx) => {
    const f = Object.values(t.recursos_red_asignados || {}).map(x => x && x.red).filter(Boolean);
    if (new Set(f).size !== f.length) throw new Error('UNIDAD '+N+', tema '+(idx+1)+': formato RED repetido dentro del tema.');
  });

  // ---- bibliografía de la unidad, indexada por ID ----
  const entradas = [...unidad.bibliografia.basica.entradas, ...unidad.bibliografia.complementaria.entradas];
  const porId = {};
  entradas.forEach(e => { porId[e.id] = e; });
  const usos = {};
  entradas.forEach(e => { usos[e.id] = []; });

  const m = {};
  const traza = [];

  const asignar = (clave, valor) => {
    const v = valor === null || valor === undefined ? '' : String(valor).trim();
    if (!v) advertencias.push('Sin valor para <<' + clave + '>>');
    m['<<' + clave + '>>'] = v;
  };

  // Filtra los IDs a los que existen de verdad en esta unidad.
  const idsValidos = (lista, clave) => {
    const pedidos = Array.isArray(lista) ? lista.map(x => String(x).trim()).filter(Boolean) : [];
    const unicos = [...new Set(pedidos)];
    const buenos = unicos.filter(id => porId[id]);
    const malos = unicos.filter(id => !porId[id]);
    if (malos.length) {
      advertencias.push(
        '<<' + clave + '>> citó fuentes que no existen en la bibliografía de la unidad y se descartaron: ' +
          malos.join(', ')
      );
    }
    return buenos;
  };

  const delSyllabus = (clave, valor, ubicacion) => {
    asignar(clave, valor);
    traza.push({ marcador: '<<' + clave + '>>', origen: 'syllabus', ubicacion, fuentes_ids: [], sustento: null });
  };

  const generado = (clave, valor, opc) => {
    asignar(clave, valor);
    const ids = idsValidos(opc.fuentes, clave);
    if (opc.requiereFuente && ids.length === 0) {
      advertencias.push('<<' + clave + '>> no quedó respaldado por ninguna fuente de la bibliografía.');
    }
    ids.forEach(id => usos[id].push('<<' + clave + '>>'));
    traza.push({
      marcador: '<<' + clave + '>>',
      origen: 'generado',
      ubicacion: opc.ubicacion || null,
      fuentes_ids: ids,
      sustento: opc.sustento ? String(opc.sustento).trim() : null
    });
  };

  // ---- Información general ----
  delSyllabus('Pregrado', general.nivel_formacion, 'Información general > Nivel de formación');
  delSyllabus('Programa', general.programa, 'Información general > Programa');
  delSyllabus('Semestre', general.semestre, 'Información general > Semestre / periodo');
  delSyllabus('Asignatura', general.asignatura, 'Información general > Denominación');
  delSyllabus('Creditos', general.creditos, 'Información general > Nro. de Créditos');

  // El resultado de aprendizaje debe ser uno de los del Syllabus, no una paráfrasis.
  const raModelo = String(ia.resultado_aprendizaje || '').trim();
  const raSyllabus = (base.resultados_aprendizaje || []).find(x => norm(x) === norm(raModelo));
  if (raSyllabus) {
    delSyllabus('Resultado_Aprendizaje', raSyllabus, 'Elementos del microcurrículo > Resultados de aprendizaje de la asignatura');
  } else {
    advertencias.push(
      '<<Resultado_Aprendizaje>> no coincide literalmente con ninguno de los resultados de aprendizaje del Syllabus; revisar.'
    );
    generado('Resultado_Aprendizaje', raModelo, { ubicacion: 'Sin correspondencia literal en el Syllabus' });
  }

  delSyllabus(
    'Indicadores',
    (unidad.indicadores_logro || []).join(' ') || unidad.indicadores_logro_raw,
    'Unidad ' + N + ' > Indicadores de logro'
  );
  delSyllabus('Duracion', unidad.horas_estimadas, 'Unidad ' + N + ' > Horas estimadas de la unidad');
  delSyllabus('N', N, 'Unidad ' + N + ' > Número de unidad');

  // ---- Desarrollo de la unidad ----
  delSyllabus('Nombre_Unidad', 'Unidad Nro. ' + N + ' — ' + unidad.nombre, 'Unidad ' + N + ' > Nombre');

  const desc = typeof ia.descripcion === 'string' ? { texto: ia.descripcion } : ia.descripcion || {};
  generado('Descripcion', desc.texto, {
    fuentes: desc.fuentes_ids,
    sustento: desc.sustento,
    ubicacion: 'Justificación de la asignatura + Unidad ' + N + ' (nombre e indicadores)',
    requiereFuente: true
  });
  // La plantilla escribe el marcador con tilde.
  m['<<Descripción>>'] = m['<<Descripcion>>'];


  const temasIa = Array.isArray(ia.temas) ? ia.temas : [];
  const nombresTemas = unidad.temas.map(t => t.nombre);

  for (let t = 1; t <= 4; t++) {
    const temaSyl = unidad.temas[t - 1];
    const temaIa = temasIa[t - 1] || {};
    const recursos = Array.isArray(temaIa.recursos) ? temaIa.recursos : [];
    const ubTema = 'Unidad ' + N + ' > Tema ' + t;

    if (!temaSyl) advertencias.push('El Syllabus no trae un tema ' + t + ' para esta unidad.');
    if (recursos.length !== 6) {
      advertencias.push('El tema ' + t + ' devolvió ' + recursos.length + ' recursos en vez de 6.');
    }

    // Si la plantilla ya escribe el número ("1. <<Nombre_Tema1>>"), esa forma se reemplaza primero
    // para no duplicarlo; replaceAllText respeta el orden de los marcadores.
    const nombreTemaN = temaSyl ? temaNumerado(temaSyl.nombre, t) : '';
    m[t + '. <<Nombre_Tema' + t + '>>'] = nombreTemaN;
    delSyllabus('Nombre_Tema' + t, nombreTemaN, ubTema + ' > Nombre');
    generado('N' + t, temaIa.semana, { ubicacion: ubTema + ' > Horas de los subtemas (reparto por semanas)' });

    // Orden fijo de la plantilla: OVI 1, OVA 1, OVI 2, OVA 2, OVI 3, OVA 3.
    const orden = [['OVI', 1], ['OVA', 1], ['OVI', 2], ['OVA', 2], ['OVI', 3], ['OVA', 3]];

    // Subtemas que aborda cada recurso, según «Asignar actividades autoaprendizaje4».
    const cobertura = (temaSyl && temaSyl.cobertura_recursos) || {};
    const cubre = Object.fromEntries(['OVI1', 'OVA1', 'OVI2', 'OVA2', 'OVI3', 'OVA3'].map((clave, p) =>
      [clave, cobertura[clave] ? cobertura[clave].indices : [[0], [0], [1], [1], [2], [2]][p]]));

    // Se usa para mostrar cada subtema una sola vez en la tabla.
    const subtemasMostrados = new Set();

    orden.forEach(([tipo, idx], posicion) => {
      const r = recursos[posicion] || {};
      if (r.tipo && (r.tipo !== tipo || r.indice !== idx)) {
        advertencias.push(
          'Tema ' + t + ', recurso ' + (posicion + 1) + ': se esperaba ' + tipo + ' ' + idx +
            ' y llegó ' + r.tipo + ' ' + r.indice + '.'
        );
      }
      const sufijo = '_' + tipo + '_' + idx + '_T' + t;
      const indices = cubre[tipo + idx] || [];
      const subs = temaSyl ? indices.map(i => temaSyl.subtemas[i]).filter(Boolean) : [];
      const textoSubtemas = subs.map(s => s.nombre).join(' / ');
      const claveSubtemas = norm(textoSubtemas);
      const ubSub = ubTema + ' > Subtema' + (indices.length > 1 ? 's ' : ' ') + indices.map(i => i + 1).join(' y ');

      const asignacionRed = temaSyl && temaSyl.recursos_red_asignados && temaSyl.recursos_red_asignados[tipo + idx];
      const formatoRed = String(asignacionRed && asignacionRed.red || '').trim();

      if (!formatoRed) {
        advertencias.push('Tema ' + t + ', ' + tipo + ' ' + idx + ': no recibió un formato RED asignado desde el catálogo del anexo 3.10.');
      }

      // El marcador RED contiene únicamente el tipo de recurso asignado.
      asignar('Red' + sufijo, formatoRed);
      traza.push({
        marcador: '<<Red' + sufijo + '>>',
        origen: formatoRed ? 'catálogo RED, numeral 3.10' : 'sin asignación',
        ubicacion: ubSub,
        fuentes_ids: [],
        sustento: null
      });

      // Columna "Contenido del recurso": el nombre específico que desglosa el subtema.
      // Si el modelo antepuso el formato RED (p. ej. "Infografías estáticas: ..."), se quita.
      const nombreRecurso = limpiarNombre(String(r.nombre || '')
        .replace(new RegExp('^\\s*' + formatoRed.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*[:\\-–—]\\s*', 'i'), ''));
      generado('Nom' + sufijo, nombreRecurso, {
        fuentes: r.fuentes_ids,
        sustento: r.sustento,
        ubicacion: ubSub,
        requiereFuente: true
      });

      // Muestra el subtema en la primera fila que lo usa.
      // Si ya apareció en otra fila, deja este marcador vacío para evitar duplicarlo.
      if (textoSubtemas && !subtemasMostrados.has(claveSubtemas)) {
        subtemasMostrados.add(claveSubtemas);
        delSyllabus('Rec' + sufijo, textoSubtemas, ubSub);
      } else {
        m['<<Rec' + sufijo + '>>'] = '';
        traza.push({
          marcador: '<<Rec' + sufijo + '>>',
          origen: textoSubtemas ? 'syllabus (repetición omitida)' : 'sin subtema',
          ubicacion: ubSub,
          fuentes_ids: [],
          sustento: null
        });
      }

      if (tipo === 'OVA') {
        const claveOva = 'OVA' + idx;
        const actividadAsignada = temaSyl && temaSyl.actividades_autoaprendizaje && temaSyl.actividades_autoaprendizaje[claveOva];
        if (!actividadAsignada) {
          advertencias.push('Tema ' + t + ', ' + claveOva + ': no tiene tipo RED asignado por el catálogo.');
        } else if (String(r.tipo_actividad || '').trim() !== actividadAsignada.red) {
          advertencias.push('Tema ' + t + ', ' + claveOva + ': el tipo devuelto no coincide con el tipo RED asignado (' + actividadAsignada.red + ').');
        }
        // La plantilla usa Adu_ en el tema 1 y Nar_ en los temas 2, 3 y 4.
        // La celda lleva solo el nombre del tipo de actividad del catálogo (numeral 3.10),
        // tal como lo asignó «Asignar actividades autoaprendizaje2».
        const nombreActividad = actividadAsignada ? actividadAsignada.red : limpiarNombre(r.tipo_actividad);
        generado((t === 1 ? 'Adu' : 'Nar') + sufijo, nombreActividad, {
          fuentes: r.fuentes_ids,
          sustento: r.sustento,
          ubicacion: ubSub + ' + Estrategias evaluativas de la unidad',
          requiereFuente: true
        });
      }

    });
  }

  // ---- Evaluaciones ----
  const evaluaciones = Array.isArray(ia.evaluaciones) ? ia.evaluaciones : [];
  let suma = 0;
  [1, 2].forEach(n => {
    const e = evaluaciones[n - 1] || {};
    const ub = 'Unidad ' + N + ' > Estrategias evaluativas + Indicadores de logro';
    generado('Objetivo_' + n, e.objetivo, { fuentes: e.fuentes_ids, ubicacion: ub });

    // Ubicación: la formativa en el tema 1 o 2 elegido al azar en «Asignar actividades
    // autoaprendizaje1»; la sumativa en todos los temas, numerados y uno por línea.
    if (n === 1) {
      const elegido = (unidad.evaluaciones_asignadas && unidad.evaluaciones_asignadas.formativa) || {};
      const delModelo = norm(String(e.tema || '').replace(/^\s*\d+\s*[.)\-–]?\s*/, ''));
      const k = [1, 2].includes(elegido.numero) ? elegido.numero
        : (nombresTemas[1] && norm(temaNumerado(nombresTemas[1], 2)).endsWith(delModelo) ? 2 : 1);
      const ubicacion = temaNumerado(nombresTemas[k - 1], k);
      if (delModelo && !norm(ubicacion).endsWith(delModelo)) {
        advertencias.push('La formativa del modelo apuntaba a "' + e.tema + '"; se ubicó en el tema ' + k + '.');
      }
      delSyllabus('Tema_1', ubicacion, 'Unidad ' + N + ' > Tema ' + k + ' (elegido al azar entre 1 y 2)');
    } else {
      delSyllabus('Tema_2', nombresTemas.map((x, i) => temaNumerado(x, i + 1)).join('\n'), 'Unidad ' + N + ' > Todos los temas');
    }

    generado('Porcentaje_' + n, e.porcentaje, { ubicacion: 'Decisión de ponderación, sin fuente en el Syllabus' });
    suma += parseFloat(String(e.porcentaje || '').replace(',', '.')) || 0;
  });
  if (Math.round(suma) !== 100) {
    advertencias.push('Los porcentajes de evaluación suman ' + suma + '% y deberían sumar 100%.');
  }

  // ---- registro de fuentes ----
  const bibliografiaRegistro = entradas.map(e => ({ ...e, citada_en: usos[e.id] }));
  const noCitadas = entradas.filter(e => usos[e.id].length === 0).map(e => e.id);

  const md = [];
  md.push('# Registro de fuentes — Unidad ' + N + ': ' + unidad.nombre);
  md.push('');
  md.push('- **Asignatura:** ' + general.asignatura + ' (' + (general.programa || 's. d.') + ')');
  md.push('- **Syllabus:** ' + (base.archivo || 's. d.') + (base.origen && base.origen.url ? ' — ' + base.origen.url : ''));
  md.push('- **Actualización del Syllabus:** ' + (general.fecha_actualizacion || 's. d.'));
  md.push('- **Nivel de verificación:** ' + NIVEL_VERIFICACION);
  md.push('');
  md.push('## Bibliografía de la unidad');
  bibliografiaRegistro.forEach(e => {
    const donde = e.citada_en.length ? e.citada_en.join(', ') : 'NO CITADA en ningún recurso';
    md.push('- **[' + e.id + ']** ' + e.texto + '  \n  Citada en: ' + donde);
  });
  md.push('');
  md.push('## Trazabilidad por marcador');
  md.push('| Marcador | Origen | Ubicación en el Syllabus | Fuentes | Sustento |');
  md.push('|---|---|---|---|---|');
  traza.forEach(t => {
    md.push(
      '| `' + t.marcador + '` | ' + t.origen + ' | ' + (t.ubicacion || '') + ' | ' +
        (t.fuentes_ids.join(', ') || '—') + ' | ' + (t.sustento || '').replace(/\|/g, '/') + ' |'
    );
  });
  if (advertencias.length) {
    md.push('');
    md.push('## Advertencias');
    advertencias.forEach(a => md.push('- ' + a));
  }

  const totalMarcadores = Object.keys(m).length;

  return {
    json: {
      archivo: base.archivo,
      origen: base.origen,
      asignatura: general.asignatura,
      unidad: N,
      nombre_unidad: unidad.nombre,
      total_unidades: base.total_unidades,
      control_formatos_red: unidad.control_formatos_red || {
        max_videos_por_unidad: 1,
        videos_asignados: videosAsignados.length,
        distribucion: {}
      },
      actividades_autoaprendizaje_asignadas: unidad.temas.map(t => ({
        tema: t.nombre,
        OVA1: t.actividades_autoaprendizaje && t.actividades_autoaprendizaje.OVA1 && t.actividades_autoaprendizaje.OVA1.red,
        OVA2: t.actividades_autoaprendizaje && t.actividades_autoaprendizaje.OVA2 && t.actividades_autoaprendizaje.OVA2.red,
        OVA3: t.actividades_autoaprendizaje && t.actividades_autoaprendizaje.OVA3 && t.actividades_autoaprendizaje.OVA3.red
      })),
      formatos_red_asignados: unidad.temas.map(t => ({
        tema: t.nombre,
        OVI1: t.recursos_red_asignados && t.recursos_red_asignados.OVI1 && t.recursos_red_asignados.OVI1.red,
        OVA1: t.recursos_red_asignados && t.recursos_red_asignados.OVA1 && t.recursos_red_asignados.OVA1.red,
        OVI2: t.recursos_red_asignados && t.recursos_red_asignados.OVI2 && t.recursos_red_asignados.OVI2.red,
        OVA2: t.recursos_red_asignados && t.recursos_red_asignados.OVA2 && t.recursos_red_asignados.OVA2.red,
        OVI3: t.recursos_red_asignados && t.recursos_red_asignados.OVI3 && t.recursos_red_asignados.OVI3.red,
        OVA3: t.recursos_red_asignados && t.recursos_red_asignados.OVA3 && t.recursos_red_asignados.OVA3.red
      })),
      marcadores: m,
      bibliografia: {
        basica: unidad.bibliografia.basica.entradas,
        complementaria: unidad.bibliografia.complementaria.entradas,
        basica_raw: unidad.bibliografia.basica.raw,
        complementaria_raw: unidad.bibliografia.complementaria.raw
      },
      registro: {
        nivel_verificacion: NIVEL_VERIFICACION,
        syllabus: {
          archivo: base.archivo,
          origen: base.origen,
          fecha_actualizacion: general.fecha_actualizacion,
          programa: general.programa,
          facultad: general.facultad
        },
        bibliografia: bibliografiaRegistro,
        referencias_no_citadas: noCitadas,
        trazabilidad: traza
      },
      registro_markdown: md.join('\n'),
      contexto_syllabus: {
        modalidad: general.modalidad,
        tipologia: general.tipologia,
        horas_totales: general.horas_totales,
        horas_trabajo_directo: general.horas_trabajo_directo,
        horas_trabajo_independiente: general.horas_trabajo_independiente,
