  const nivel = nivelDe(j.general?.nivel_formacion);
  const ensenanzaDe = tema => ((tema && tema.ensenanza) || unidad.ensenanza || { metodologias: [], tecnicas: [] });
  const tecnicasDe = tema => (ensenanzaDe(tema).tecnicas || []).map(t => ({ ...t, tipo: tipoTecnica(t.nombre) }));
  const rnd = azarSemilla(hashTexto([unidad.numero, unidad.nombre, j.general?.asignatura, nivel].join('|')));
  const asignaciones = temas.map(() => ({}));
  const slots = [];
  temas.forEach((tema, temaIndex) => {
    const cobertura = coberturaRecursos((tema.subtemas || []).length);
    ORDEN.forEach(([clave, tipo, indice], posicion) => {
      const subindices = cobertura[posicion];
      slots.push({ tema, temaIndex, clave, tipo, indice, subindices, texto: textoDelSlot(tema, subindices) });
    });
  });
  // Se elige una sola posicion OVI para el posible video. No se obliga a
  // inventar videos si no existen recursos OVI.
  const elegiblesVideo = slots.filter(s => s.tipo === 'OVI' && /demostr|procedim|aplic|practic|formul|diseñ|constru|explic/.test(normalizar(s.texto)));
  const videoSlot = elegiblesVideo.length
    ? barajar(elegiblesVideo, rnd).sort((a, b) => {
        const pertinencia = s => /demostr|procedim|aplic|practic|formul|diseñ|constru|explic/.test(normalizar(s.texto)) ? 1 : 0;
        return pertinencia(b) - pertinencia(a);
      })[0]
    : null;
  const usoPorFormato = new Map();
  let videosUsados = 0;
  let podcastsUsados = 0;
  let anterior = '';
  for (let temaIndex = 0; temaIndex < temas.length; temaIndex++) {
    const delTema = slots.filter(s => s.temaIndex === temaIndex);
    const usadosTema = new Set();
    const familiasTema = new Set();
    // Si el Syllabus declara técnicas de recurso (lectura, visual…), todos los recursos prefieren esas familias mientras queden formatos disponibles.
    const kindsPref = new Set(tecnicasDe(temas[temaIndex]).map(t => t.tipo).filter(k => KINDS_RECURSO.has(k)));
    for (const slot of delTema) {
      const esSlotVideo = videoSlot === slot && videosUsados < MAX_VIDEOS_UNIDAD;
      let candidatos = CATALOGO_RED.filter(c => esSlotVideo ? ES_VIDEO(c) : !ES_VIDEO(c));
      if (!esSlotVideo) {
        candidatos = candidatos.filter(c => !ES_PODCAST(c) || podcastsUsados < MAX_PODCASTS_UNIDAD);
      }
      candidatos = candidatos.filter(c => !usadosTema.has(c.red));
      if (!esSlotVideo && kindsPref.size) {
        const pref = candidatos.filter(c => kindsPref.has(tipoDeRed(c.red)));
        if (pref.length) candidatos = pref;
      }
      // Nunca forzar una linea de tiempo sobre un subtema sin dimension temporal.
      const pertinentes = candidatos.filter(c => !normalizar(c.red).includes('lineas de tiempo') || cronologico(normalizar(slot.texto)));
      if (pertinentes.length) candidatos = pertinentes;
      const sinFamiliaRepetida = candidatos.filter(c => !familiasTema.has(familia(c.red)));
      if (sinFamiliaRepetida.length) candidatos = sinFamiliaRepetida;
      if (!candidatos.length) throw new Error('No hay RED disponible para unidad '+unidad.numero+', tema '+(temaIndex+1)+', '+slot.clave);
      // Cubrir primero los formatos menos usados; respetar prioridad por nivel
      // y, en igualdad, la pertinencia pedagógica del subtema.
      const menosUsos = Math.min(...candidatos.map(c => usoPorFormato.get(c.red) || 0));
      candidatos = candidatos.filter(c => (usoPorFormato.get(c.red) || 0) === menosUsos);
      const mejorPrioridad = Math.min(...candidatos.map(c => PRIORIDAD[c.prioridad[nivel]] ?? 3));
      candidatos = candidatos.filter(c => (PRIORIDAD[c.prioridad[nivel]] ?? 3) === mejorPrioridad);
      const maxAfinidad = Math.max(...candidatos.map(c => afinidadRed(c.red, slot.texto, slot.tipo)));
      candidatos = candidatos.filter(c => afinidadRed(c.red, slot.texto, slot.tipo) === maxAfinidad);
      const sinRepetir = candidatos.filter(c => c.red !== anterior);
      if (sinRepetir.length) candidatos = sinRepetir;
      const elegido = barajar(candidatos, rnd)[0];
      usadosTema.add(elegido.red);
      familiasTema.add(familia(elegido.red));
      usoPorFormato.set(elegido.red, (usoPorFormato.get(elegido.red) || 0) + 1);
      if (ES_VIDEO(elegido)) videosUsados++;
      if (ES_PODCAST(elegido)) podcastsUsados++;
      anterior = elegido.red;
      asignaciones[temaIndex][slot.clave] = {
        ...elegido,
        prioridad_aplicada: elegido.prioridad[nivel],
        nivel_aplicado: nivel,
        ciclo: 1 + (usoPorFormato.get(elegido.red) - 1),
        limite_video_por_unidad: MAX_VIDEOS_UNIDAD
      };
    }
  }
  if (videosUsados > MAX_VIDEOS_UNIDAD) throw new Error('Regla violada: mas de un video en unidad '+unidad.numero);
  if (podcastsUsados > MAX_PODCASTS_UNIDAD) throw new Error('Regla violada: mas de un podcast en unidad '+unidad.numero);
  // Actividades por tema: primero las que piden las técnicas pedagógicas del Syllabus (estudio de casos, simulación…),
  // en el orden en que el Syllabus las declara; lo que falte se completa con el catálogo según el nivel de formación.
  const relleno = [];
  for (const prio of ['Prioritaria', 'Complementaria', 'Ocasional']) relleno.push(...barajar(CATALOGO.filter(c => c.prioridad[nivel] === prio), rnd));
  relleno.sort((a, b) => (tipoDeActividad(a.red) === 'practica' ? 0 : 1) - (tipoDeActividad(b.red) === 'practica' ? 0 : 1));
  const actividadesTema = temas.map(tema => {
    const lista = [];
    for (const t of tecnicasDe(tema)) {
      if (!KINDS_ACTIVIDAD.has(t.tipo) || lista.length >= 3) continue;
      const a = actividadParaTecnica(t);
      if (a && !lista.some(x => x.red === a.red)) lista.push({ ...a, tecnica_origen: t.nombre });
    }
    for (const r of relleno) {
      if (lista.length >= 3) break;
      if (!lista.some(x => x.red === r.red)) lista.push({ ...r, tecnica_origen: null });
    }
    return lista;
  });

  // Técnica y metodología de cada fila de la tabla (OVI 1, OVA 1, … OVA 3).
  const filasTecnica = (tema, reds) => {
    const tecnicas = tecnicasDe(tema);
    const metodologias = ensenanzaDe(tema).metodologias || [];
    const filas = {};
    ORDEN.forEach(([clave]) => {
      // Matriz RED: la técnica de la fila es la familia pedagógica de su formato RED. Si el Syllabus declara esa
      // familia, se usa su redacción literal; si no, el nombre de la familia de la matriz.
      const kind = tipoDeRed(reds[clave] && reds[clave].red);
      const delSyllabus = tecnicas.find(x => x.tipo === kind) || null;
      const tecnica = delSyllabus
        ? { nombre: delSyllabus.nombre, proposito: delSyllabus.proposito, origen: 'Syllabus' }
        : { nombre: FAMILIAS[kind], proposito: '', origen: 'matriz RED' };
      const met = elegirMetodologia(metodologias, delSyllabus || tecnicas[0]);
      filas[clave] = { tecnica, metodologia: met ? { nombre: met.nombre } : null };
    });
    return filas;
  };

  // Evaluaciones del Syllabus: las formativas (hasta 2, como la plantilla) se reparten los temas en orden
  // (1-2 y 3-4); la sumativa integra todos. Porcentajes: 60 % entre las formativas y 40 % la sumativa.
  const evSyl = unidad.evaluacion_syllabus || { formativas: [], sumativas: [] };
  const formativasUsadas = evSyl.formativas.slice(0, 2);
  const mitad = Math.ceil(temas.length / 2);
  const rango = (a, b) => temas.map((t, i) => ({ numero: i + 1, nombre: t.nombre })).slice(a, b);
  const grupos = formativasUsadas.length <= 1 ? [rango(0, temas.length)] : [rango(0, mitad), rango(mitad, temas.length)];
  const evaluaciones_asignadas = {
    formativas: formativasUsadas.map((f, k) => ({ numero: k + 1, ...f, temas: grupos[k], porcentaje: Math.round(60 / formativasUsadas.length) + '%' })),
    sumativa: evSyl.sumativas[0] ? { ...evSyl.sumativas[0], temas: rango(0, temas.length), porcentaje: '40%' } : null,
    formativas_en_syllabus: evSyl.formativas.length
  };
  const temasPlan = temas.map((tema, i) => ({
    ...tema,
    // Qué subtema(s) aborda cada recurso; lo usan el prompt y «Armar salida2».
    cobertura_recursos: Object.fromEntries(ORDEN.map(([clave], posicion) => {
      const indices = coberturaRecursos((tema.subtemas || []).length)[posicion];
      return [clave, { indices, subtemas: indices.map(k => nombreSubtema((tema.subtemas || [])[k])) }];
    })),
    recursos_red_asignados: asignaciones[i],
    actividades_autoaprendizaje: {
      OVA1: { ...actividadesTema[i][0], nivel_aplicado: nivel },
      OVA2: { ...actividadesTema[i][1], nivel_aplicado: nivel },
      OVA3: { ...actividadesTema[i][2], nivel_aplicado: nivel }
    },
    filas_tecnica: filasTecnica(tema, asignaciones[i])
  }));
  return {
    json: {
      ...j,
      nivel_actividades: nivel,
      unidad: {
        ...unidad,
        temas: temasPlan,
        evaluaciones_asignadas,
        control_formatos_red: {
          max_videos_por_unidad: MAX_VIDEOS_UNIDAD,
          videos_asignados: videosUsados,
          max_podcasts_por_unidad: MAX_PODCASTS_UNIDAD,
          podcasts_asignados: podcastsUsados,
          distribucion: Object.fromEntries(usoPorFormato)
        }
      }
    },
    pairedItem: { item: itemIndex }
  };
});

