parameters.jsCode:
// Nodo Code: «Separar subtemas en la tabla» · Modo: Run Once for All Items
// En la plantilla la celda «Subtemas» viene combinada de dos en dos (OVI 1 + OVA 1, OVI 2 + OVA 2
// y OVI 3 + OVA 3), que es lo correcto cuando el tema tiene 3 subtemas. Con 4 o más subtemas
// el OVA aborda un subtema propio: aquí se descombina esa celda y se escribe en ella su
// marcador <<Rec_OVA_N_TT>>, que luego llena replaceAllText.
// Si la tabla no tiene la forma esperada, el subtema del OVA se escribe en la celda
// combinada, debajo del subtema del OVI (respaldo), para que nunca se pierda.

const SIN_CAMBIOS = { replaceAllText: { containsText: { text: '<<__sin_cambios__>>', matchCase: true }, replaceText: '' } };
const textoParrafo = el => (el.paragraph?.elements || []).map(e => e.textRun?.content || '').join('');
const textoCelda = c => (c?.content || []).map(textoParrafo).join('');

// Indicadores de logro de la unidad: se insertan en el lugar de <<Indicadores>> (uno por línea, con una línea en blanco entre
// ellos) y la etiqueta "Indicador de Logro N:" queda en negrita. Si no se halla el marcador, el reemplazo normal lo escribe sin formato.
const SEPARADOR_INDICADORES = '\n\n';
function formatoIndicadores(tablas, base) {
  const MARCADOR = '<<Indicadores>>';
  const lista = (base.indicadores_logro || []).map(x => String(x).trim()).filter(Boolean);
  if (!lista.length) return { requests: [] };
  let inicio = null;
  for (const el of tablas) {
    for (const fila of el.table.tableRows || []) {
      for (const celda of fila.tableCells || []) {
        for (const bloque of celda.content || []) {
          for (const e of (bloque.paragraph && bloque.paragraph.elements) || []) {
            const t = e.textRun && e.textRun.content;
            if (inicio === null && t && t.includes(MARCADOR) && Number.isInteger(e.startIndex)) inicio = e.startIndex + t.indexOf(MARCADOR);
          }
        }
      }
    }
  }
  if (inicio === null) return { requests: [] };
  const texto = lista.join(SEPARADOR_INDICADORES);
  const requests = [
    { insertText: { location: { index: inicio }, text: texto } },
    { deleteContentRange: { range: { startIndex: inicio + texto.length, endIndex: inicio + texto.length + MARCADOR.length } } }
  ];
  let pos = inicio;
  for (const ind of lista) {
    const m = /^Indicador de Logro\s*\d+\s*:/i.exec(ind) || /^[^:]{1,40}:/.exec(ind);
    if (m) requests.push({ updateTextStyle: { range: { startIndex: pos, endIndex: pos + m[0].length }, textStyle: { bold: true }, fields: 'bold' } });
    pos += ind.length + SEPARADOR_INDICADORES.length;
  }
  return { requests, p: inicio };
}

// Posición del marcador dentro del documento (índice del primer carácter), o null si no se encuentra en una sola corrida de texto.
function posicionDe(tablas, marcador) {
  for (const el of tablas) {
    for (const fila of el.table.tableRows || []) {
      for (const celda of fila.tableCells || []) {
        for (const bloque of celda.content || []) {
          for (const e of (bloque.paragraph && bloque.paragraph.elements) || []) {
            const t = e.textRun && e.textRun.content;
            if (t && t.includes(marcador) && Number.isInteger(e.startIndex)) return e.startIndex + t.indexOf(marcador);
          }
        }
      }
    }
  }
  return null;
}

// Metodología activa de aprendizaje: en la celda combinada de cada tema, el NOMBRE de la metodología va en negrita ("Aprendizaje
// Basado en Retos:") y su descripción en texto normal. Si no se halla el marcador, el reemplazo normal lo escribe sin formato.
function formatoMetodologias(tablas, base) {
  const grupos = [];
  for (const [marcador, prefijos] of Object.entries(base.metodologias_negrita || {})) {
    const texto = String((base.marcadores || {})[marcador] || '');
    if (!texto || !(prefijos || []).length) continue;
    const inicio = posicionDe(tablas, marcador);
    if (inicio === null) continue;
    const requests = [
      { insertText: { location: { index: inicio }, text: texto } },
      { deleteContentRange: { range: { startIndex: inicio + texto.length, endIndex: inicio + texto.length + marcador.length } } }
    ];
    let cursor = 0;
    for (const pref of prefijos) {
      const i = texto.indexOf(pref, cursor);
      if (i < 0) continue;
      requests.push({ updateTextStyle: { range: { startIndex: inicio + i, endIndex: inicio + i + pref.length }, textStyle: { bold: true }, fields: 'bold' } });
      cursor = i + pref.length;
    }
    grupos.push({ p: inicio, requests });
  }
  return grupos;
}

// Formato general del documento: letra Arial 10 en todo el cuerpo (celdas incluidas) y la presentación de la unidad con
// alineación justificada. No cambia ningún índice, por eso va al principio de las solicitudes.
function formatoGeneral(body) {
  const contenido = (body && body.content) || [];
  const fin = contenido.length ? contenido[contenido.length - 1].endIndex : 0;
  const requests = [];
  if (Number.isInteger(fin) && fin > 2) {
    requests.push({ updateTextStyle: { range: { startIndex: 1, endIndex: fin - 1 }, textStyle: { weightedFontFamily: { fontFamily: 'Arial' }, fontSize: { magnitude: 10, unit: 'PT' } }, fields: 'weightedFontFamily,fontSize' } });
  }
  const justificar = lista => {
    for (const el of lista) {
      if (el.paragraph) {
        if (textoParrafo(el).includes('<<Presentacion_Unidad>>') && Number.isInteger(el.startIndex) && Number.isInteger(el.endIndex)) {
          requests.push({ updateParagraphStyle: { range: { startIndex: el.startIndex, endIndex: el.endIndex }, paragraphStyle: { alignment: 'JUSTIFIED' }, fields: 'alignment' } });
        }
      } else if (el.table) {
        for (const fila of el.table.tableRows || []) for (const celda of fila.tableCells || []) justificar(celda.content || []);
      }
    }
  };
  justificar(contenido);
  return requests;
}

return $input.all().map((item, i) => {
  const base = $('Conservar unidad y copia1').all()[i].json;
  const marcadores = base.marcadores || {};
  const tablas = (item.json.body?.content || []).filter(el => el.table);
  const descombinar = [];
  const inserciones = [];
  const respaldo = {};
  const separados = [];
  const advertencias = [];

  for (let t = 1; t <= 4; t++) {
    for (const k of [1, 2, 3]) {
      const marcadorOva = '<<Rec_OVA_' + k + '_T' + t + '>>';
      const marcadorOvi = '<<Rec_OVI_' + k + '_T' + t + '>>';
      if (!String(marcadores[marcadorOva] || '').trim()) continue; // comparte subtema con el OVI

      let ubicado = null;
      for (const el of tablas) {
        const filas = el.table.tableRows || [];
        const r = filas.findIndex(f => (f.tableCells || []).some(c => textoCelda(c).includes('<<Nom_OVA_' + k + '_T' + t + '>>')));
        if (r > 0) { ubicado = { el, filas, r }; break; }
      }
      const celdaOva = ubicado && ubicado.filas[ubicado.r].tableCells[0];
      const celdaOvi = ubicado && ubicado.filas[ubicado.r - 1].tableCells[0];
      const formaEsperada = celdaOva && celdaOvi &&
        textoCelda(celdaOvi).includes(marcadorOvi) && !textoCelda(celdaOva).includes('<<Nom_') &&
        celdaOva.content && celdaOva.content[0] && Number.isInteger(celdaOva.content[0].startIndex);

      if (!formaEsperada) {
        respaldo[marcadorOvi] = [marcadores[marcadorOvi], marcadores[marcadorOva]].filter(Boolean).join('\n');
        advertencias.push('Tema ' + t + ': no se pudo separar la celda de subtemas de OVI ' + k + ' y OVA ' + k + '; ambos subtemas quedan en la misma celda.');
        continue;
      }
      if (textoCelda(celdaOva).includes(marcadorOva)) continue; // la plantilla ya trae la celda separada
      if ((celdaOvi.tableCellStyle?.rowSpan || 1) > 1) {
        descombinar.push({
          unmergeTableCells: {
            tableRange: {
              tableCellLocation: { tableStartLocation: { index: ubicado.el.startIndex }, rowIndex: ubicado.r - 1, columnIndex: 0 },
              rowSpan: 2,
              columnSpan: 1
            }
          }
        });
      }
      inserciones.push({ insertText: { location: { index: celdaOva.content[0].startIndex }, text: marcadorOva } });
      separados.push([marcadorOvi, marcadorOva]);
    }
  }

  // Descombinar no mueve el texto; las inserciones van de la última a la primera
  // para que los índices calculados sigan siendo válidos.
  inserciones.sort((a, b) => b.insertText.location.index - a.insertText.location.index);
  const formato = formatoIndicadores(tablas, base);
  // Cada inserción se aplica de la posición más alta a la más baja, para que los índices ya calculados sigan siendo válidos.
  const grupos = inserciones.map(r => ({ p: r.insertText.location.index, requests: [r] }));
  if (formato.requests.length) grupos.push({ p: formato.p, requests: formato.requests });
  grupos.push(...formatoMetodologias(tablas, base));
  grupos.sort((a, b) => b.p - a.p);
  const estructura = [...formatoGeneral(item.json.body), ...descombinar, ...grupos.flatMap(g => g.requests)];

  // Respaldo: el subtema del OVA va en la celda combinada, debajo del del OVI.
  const conRespaldo = tabla => (base.replace_requests || []).map(r => {
    const m = r.replaceAllText?.containsText?.text;
    return m in tabla ? { replaceAllText: { ...r.replaceAllText, replaceText: tabla[m] } } : r;
  });
  // Por si Google Docs rechaza la separación: todos los pares quedan en su celda combinada.
  const respaldoTotal = { ...respaldo };
  for (const [ovi, ova] of separados) respaldoTotal[ovi] = [marcadores[ovi], marcadores[ova]].filter(Boolean).join('\n');

  return {
    json: {
      ...base,
      estructura_requests: estructura.length ? estructura : [SIN_CAMBIOS],
      replace_requests: conRespaldo(respaldo),
      replace_requests_respaldo: conRespaldo(respaldoTotal),
      advertencias: [...(base.advertencias || []), ...advertencias]
    },
    pairedItem: { item: i }
  };
});

// Nodo Code: «Elegir reemplazos1» · Modo: Run Once for All Items
// Si Google Docs aceptó la separación de celdas se usan los reemplazos normales; si la
// rechazó, los de respaldo (el subtema del OVA queda en la celda combinada del OVI).
return $input.all().map((item, i) => {
  const base = $('Separar subtemas en la tabla2').all()[i].json;
  const fallo = item.json && item.json.error;
  return {
