};

// Hay cursos con más de un resultado de aprendizaje: se leen TODOS (uno por párrafo, o varios numerados en el mismo párrafo).
function celdaDespuesDe(...etiquetas) {
  const objetivo = etiquetas.map(norm);
  for (const filas of tablas) {
    for (const celdas of filas) {
      for (let i = 0; i < celdas.length - 1; i++) {
        if (objetivo.includes(norm(celdas[i])) && String(celdas[i + 1] || '').trim()) return celdas[i + 1];
      }
    }
  }
  return '';
}
const raCruda = celdaDespuesDe('Resultados de aprendizaje de la asignatura', 'Resultado de aprendizaje de la asignatura', 'Resultados de aprendizaje', 'Resultado de aprendizaje');
let resultados_aprendizaje = [];
{
  const lineas = String(raCruda).split('\n').map(x => x.trim()).filter(Boolean);
  if (lineas.some(l => /^\d+\s*[.)]/.test(l))) {
    for (const l of lineas) {
      if (/^\d+\s*[.)]/.test(l) || !resultados_aprendizaje.length) resultados_aprendizaje.push(l);
      else resultados_aprendizaje[resultados_aprendizaje.length - 1] += ' ' + l;
    }
