    if (partes.length > 1) resultados_aprendizaje = partes;
  }
}

// ---------- estrategias de enseñanza y evaluativas (celdas de la tabla de temas) ----------
// Todo sale literal del Syllabus. La celda de enseñanza trae una "Metodología Activa de Aprendizaje" y una lista
// de "Técnicas Pedagógicas", cada una con su "Propósito y Aplicación". La celda evaluativa trae las evaluaciones
// formativas y la sumativa, cada una con Estrategia, Mecanismo y Descripción (Ind-xx).

// Parte un bloque en elementos de lista: "- Algo. - Otro" (con o sin espacio tras el guion).
const PARTIR_LISTA = /(?:^|\s)-\s+(?=[A-ZÁÉÍÓÚÑ¿¡])|(?<=[.:;)])-\s*(?=[A-ZÁÉÍÓÚÑ])/;
const sinPuntoFinal = s => String(s || '').replace(/[\s.;:,]+$/, '').trim();

function parsearEnsenanza(raw) {
  const t = aplanar(raw);
  const vacio = { metodologias: [], tecnicas: [] };
  if (!t) return vacio;
  const iMet = t.search(/Metodolog[ií]as?\s+Activas?\s+de\s+Aprendizaje\s*:?/i);
  const iTec = t.search(/T[eé]cnicas?\s+Pedag[oó]gicas?\s*:?/i);
  const bloqueMet = iMet < 0 ? '' : t.slice(iMet, iTec > iMet ? iTec : undefined).replace(/^Metodolog[ií]as?\s+Activas?\s+de\s+Aprendizaje\s*:?\s*/i, '');
  const bloqueTec = iTec < 0 ? '' : t.slice(iTec, iMet > iTec ? iMet : undefined).replace(/^T[eé]cnicas?\s+Pedag[oó]gicas?\s*:?\s*/i, '');

  const metodologias = bloqueMet.split(PARTIR_LISTA).map(x => x.trim()).filter(Boolean).map(x => {
    const i = x.indexOf(':');
    const nombre = i > 0 && i <= 120 ? x.slice(0, i) : x.split(/\s+/).slice(0, 8).join(' ');
    return { nombre: sinPuntoFinal(nombre), descripcion: i > 0 && i <= 120 ? x.slice(i + 1).trim() : x };
  });

  const tecnicas = bloqueTec.split(PARTIR_LISTA).map(x => x.trim()).filter(Boolean).map(x => {
    const m = /Prop[oó]sito\s+y\s+Aplicaci[oó]n\s*:?/i.exec(x);
    if (m) return { nombre: sinPuntoFinal(x.slice(0, m.index)), proposito: x.slice(m.index + m[0].length).trim() };
    const corte = x.search(/[.:]/);
    return corte > 0 ? { nombre: sinPuntoFinal(x.slice(0, corte)), proposito: x.slice(corte + 1).trim() } : { nombre: sinPuntoFinal(x), proposito: '' };
  }).filter(x => x.nombre);

  return { metodologias, tecnicas };
}

function parsearEvaluativas(raw) {
  const t = aplanar(raw);
  const out = { formativas: [], sumativas: [] };
  if (!t) return out;
  const re = /Evaluaci[oó]n(?:es)?\s+(formativa|sumativa)s?\s*[.:]?/gi;
  const cortes = [];
  let m;
  while ((m = re.exec(t))) cortes.push({ tipo: m[1].toLowerCase(), ini: m.index, fin: re.lastIndex });
  cortes.forEach((c, i) => {
    const cuerpo = t.slice(c.fin, i + 1 < cortes.length ? cortes[i + 1].ini : undefined);
    const entradas = cuerpo.split(/-?\s*(?=Estrategia\s*:)/i).map(x => x.trim()).filter(x => /^Estrategia\s*:/i.test(x));
    for (const e of entradas) {
      const g = /^Estrategia\s*:\s*([\s\S]*?)\s*Mecanismo\s*:\s*([\s\S]*?)\s*Descripci[oó]n\s*:\s*([\s\S]*)$/i.exec(e);
      if (!g) { out[c.tipo === 'formativa' ? 'formativas' : 'sumativas'].push({ estrategia: sinPuntoFinal(e.replace(/^Estrategia\s*:\s*/i, '')), mecanismo: '', descripcion: '', indicadores: [] }); continue; }
      const descripcion = g[3].replace(/\s*-\s*$/, '').trim();
      const indicadores = [...new Set((descripcion.match(/Ind-\d+/gi) || []).map(x => 'Ind-' + x.slice(4)))];
      out[c.tipo === 'formativa' ? 'formativas' : 'sumativas'].push({
        estrategia: sinPuntoFinal(g[1]), mecanismo: sinPuntoFinal(g[2]), descripcion, indicadores
      });
    }
  });
  return out;
}

// ---------- unidades ----------

const unidades = [];

// Cada unidad empieza en la fila cuya primera celda dice "Unidad Nro. N" (o "Unidad N°", "Unidad No.").
// Word une en una sola tabla las tablas que quedan pegadas, así que se corta por esas filas y no por tabla.
const RE_UNIDAD = /^Unidad\s*(?:Nro\.?|N[°ºo]\.?|N[uú]mero)\s*(\d+)|^Unidad\s+(\d+)\s*$/i;
const tablasUnidad = [];
for (const filas of tablas) {
  let enCurso = null;
  for (const fila of filas) {
    if (RE_UNIDAD.test(aplanar(fila[0]))) tablasUnidad.push(enCurso = [fila]);
    else if (enCurso) enCurso.push(fila);
  }
}

for (const filas of tablasUnidad) {
  const m = RE_UNIDAD.exec(aplanar(filas[0][0]));
  const numero = Number(m[1] || m[2]);
  if (unidades.some(u => u.numero === numero)) continue;
  const nombre = aplanar(filas[0][1]);
  const horas = aplanar(filas[0][3]);

  const filaInd = filas.find(c => norm(c[0]).startsWith('indicadores de logro'));
  const indicadoresRaw = filaInd ? aplanar(filaInd[1]) : '';
  const indicadores = indicadoresRaw
    .split(/(?=Indicador de Logro\s*\d+\s*:)/gi)
    .map(x => x.trim())
    .filter(Boolean);

  const iCabecera = filas.findIndex(
    c => norm(c[0]) === 'temas'
  );
  const iBiblio = filas.findIndex(c => norm(c[0]).startsWith('bibliografia'));
  const fin = iBiblio === -1 ? filas.length : iBiblio;

  const temas = [];
  let actual = null;
  let estrategias_ensenanza = '';
  let estrategias_evaluativas = '';
  const celdasEns = [];
  const celdasEval = [];

  for (let i = iCabecera + 1; i < fin; i++) {
    const c = filas[i];
    if (!c) continue;
    if ((norm(c[2]) === 'ad' && norm(c[3]) === 'ei') || (norm(c[0]) === 'ad' && norm(c[1]) === 'ei')) continue; // subcabecera AD/EI
    const subtema = aplanar(c[1]);
    if (!subtema) continue;

    const nombreTema = aplanar(c[0]);
    if (nombreTema || !actual) {
      actual = { nombre: nombreTema, subtemas: [] };
      temas.push(actual);
    }
    actual.subtemas.push({
      nombre: subtema,
      horas_trabajo_directo: aplanar(c[2]),
      horas_trabajo_independiente: aplanar(c[3])
    });
    if (!estrategias_ensenanza && (c[4] || '').trim()) estrategias_ensenanza = c[4].trim();
    if (!estrategias_evaluativas && (c[5] || '').trim()) estrategias_evaluativas = c[5].trim();
    if ((c[4] || '').trim()) celdasEns.push({ tema: actual, raw: c[4].trim() });
    if ((c[5] || '').trim()) celdasEval.push({ raw: c[5].trim() });
  }

  // La celda de enseñanza suele estar combinada para toda la unidad; si cada tema trae la suya, cada tema usa la propia.
  const ensenanza = parsearEnsenanza(estrategias_ensenanza);
  if (new Set(celdasEns.map(x => aplanar(x.raw))).size > 1) celdasEns.forEach(x => { x.tema.ensenanza = parsearEnsenanza(x.raw); });
  const evalPars = celdasEval.map(x => parsearEvaluativas(x.raw));
  const evaluacion_syllabus = { formativas: evalPars.flatMap(x => x.formativas), sumativas: evalPars.flatMap(x => x.sumativas) };

  function bibliografiaTras(prefijo, letra) {
    const i = filas.findIndex(c => norm(c[0]).startsWith(norm(prefijo)));
    if (i === -1) return { raw: '', entradas: [] };
    // El texto puede estar en la misma fila (segunda celda) o en la siguiente.
    const raw = ((filas[i][1] || '').trim() || (filas[i + 1] ? (filas[i + 1][0] || '').trim() : ''));
    const entradas = splitRefs(raw).map((t, k) =>
      entradaBibliografica(t, 'U' + numero + '-' + letra + (k + 1), letra === 'B' ? 'basica' : 'complementaria')
    );
    return { raw: aplanar(raw), entradas };
  }

  unidades.push({
    numero,
    nombre,
    horas_estimadas: horas,
    indicadores_logro: indicadores,
    indicadores_logro_raw: indicadoresRaw,
    temas,
    estrategias_ensenanza,
    estrategias_evaluativas,
    ensenanza,
    evaluacion_syllabus,
    bibliografia: {
      basica: bibliografiaTras('Bibliografía básica', 'B'),
      complementaria: bibliografiaTras('Bibliografía complementaria', 'C')
    }
  });
}

if (unidades.length === 0) {
  throw new Error(
    'No se encontró ninguna unidad ("Unidad Nro. N") en el documento. ' +
      '¿Es un Syllabus con el formato esperado?'
  );
}

// ---------- unidad solicitada ----------
// ?unidad=2 en el webhook procesa solo esa unidad; sin el parámetro, todas.
const consulta = ($('Webhook Syllabus1').first().json.query) || {};
const pedida = consulta.unidad ? Number(consulta.unidad) : null;
const seleccionadas = pedida ? unidades.filter(u => u.numero === pedida) : unidades;

if (seleccionadas.length === 0) {
  throw new Error(
    'El documento no tiene una Unidad Nro. ' + pedida + '. Unidades disponibles: ' +
      unidades.map(u => u.numero).join(', ')
  );
}

const origen = $('Preparar DOCX1').first().json.origen || { tipo: 'archivo', url: null };

// Lo que recibe el modelo: solo lo necesario, con la bibliografía ya numerada.
return seleccionadas.map(unidad => ({
  json: {
    archivo: $('Preparar DOCX1').first().json.original_file_name || null,
    origen,
    general,
    resultados_aprendizaje,
    unidad,
    total_unidades: unidades.length
  }
}));

// Nodo Code: "Armar salida"
// Combina lo extraído del Syllabus (dato literal) con lo generado por el modelo
// y produce los marcadores de la plantilla, la bibliografía de la unidad y el
// REGISTRO DE FUENTES: para cada marcador, si sale del Syllabus o fue generado,
// dónde está en el Syllabus y en qué referencias se apoya.
//
// Garantías que se verifican aquí, no en el modelo:
//  - Solo se aceptan IDs de bibliografía que existan en la unidad. Los demás se
//    descartan y quedan como advertencia.
//  - Donde el Syllabus ya tiene el dato, manda el Syllabus.
//  - El resultado de aprendizaje debe coincidir con uno del Syllabus.

const extraidos = (() => {
  const base = 'Asignar actividades autoaprendizaje';
  for (const sufijo of ['5', '', '1', '2', '3', '4', '6', '7', '8']) {
    try { const r = $(base + sufijo).all(); if (r && r.length) return r; } catch (e) { /* ese nombre no existe o no está conectado */ }
  }
  throw new Error('No se encontró el nodo "' + base + '" conectado antes de "Armar salida". Revisa cómo se llama en el lienzo.');
})();
const generados = $input.all();

const norm = s =>
  String(s || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

// Nombres cortos para celdas: sin comillas ni punto final, espacios simples y mayúscula inicial.
const limpiarNombre = s => {
  const t = String(s || '').replace(/["“”«»]/g, '').replace(/\s+/g, ' ').trim().replace(/[.;:,]+$/, '').trim();
  return t ? t.charAt(0).toLocaleUpperCase('es') + t.slice(1) : '';
};
// "1.Fundamentos", "Fundamentos" o "1 - Fundamentos" -> "1. Fundamentos".
const temaNumerado = (nombre, n) =>
  n + '. ' + limpiarNombre(String(nombre || '').replace(/^\s*\d+\s*[.)\-–]?\s*/, ''));

const NIVEL_VERIFICACION =
  'Vinculación por título y tema. El modelo no leyó el contenido de las obras: ' +
  'una persona debe validar que cada fuente realmente sustenta el recurso.';

const salida = generados.map((item, indice) => {
  const base = extraidos[indice] ? extraidos[indice].json : extraidos[0].json;
  const ia = item.json.output || item.json;

  const general = base.general;
  const unidad = base.unidad;
  const N = unidad.numero;
  const advertencias = [];
  const tecnicasMatriz = new Set();
  const repetidosTema = [];


  // CONTROL DURO DE FORMATOS: los tres tipos de video cuentan como UNO.
  const formatosAsignados = (unidad.temas || []).flatMap(tema =>
    Object.values(tema.recursos_red_asignados || {}).map(x => String(x && x.red || ''))
  );
  const videosAsignados = formatosAsignados.filter(f => /^videos?\s/i.test(f));
  const podcastsAsignados = formatosAsignados.filter(f => /podcast/i.test(f));
  if (videosAsignados.length > 1) {
    throw new Error('UNIDAD ' + N + ': el maximo es UN VIDEO sumando academico, explicativo y micro-learning. Se encontraron: ' + videosAsignados.join(', '));
  }
  if (podcastsAsignados.length > 1) {
    throw new Error('UNIDAD ' + N + ': maximo un podcast para garantizar variedad de recursos.');
  }
  (unidad.temas || []).forEach((t, idx) => {
    // Un formato solo puede repetirse en el tema cuando las familias de las técnicas del Syllabus no tienen más formatos (viene marcado).
    const f = Object.values(t.recursos_red_asignados || {}).filter(x => x && x.red && !x.repetido_en_tema).map(x => x.red);
    if (new Set(f).size !== f.length) throw new Error('UNIDAD '+N+', tema '+(idx+1)+': formato RED repetido dentro del tema.');
  });

  // ---- bibliografía de la unidad, indexada por ID ----
  const entradas = [...unidad.bibliografia.basica.entradas, ...unidad.bibliografia.complementaria.entradas];
  const porId = {};
  entradas.forEach(e => { porId[e.id] = e; });
  const usos = {};
  entradas.forEach(e => { usos[e.id] = []; });

  const m = {};
  const traza = [];

  const asignar = (clave, valor) => {
    // Se quita la coletilla "en todos los temas de la unidad" de cualquier texto de la plantilla.
    const v = (valor === null || valor === undefined ? '' : String(valor)).replace(/\s+en todos los temas de la unidad(?=[\s.,;:]|$)/gi, '').trim();
    if (!v) advertencias.push('Sin valor para <<' + clave + '>>');
    m['<<' + clave + '>>'] = v;
  };

  // Filtra los IDs a los que existen de verdad en esta unidad.
  const idsValidos = (lista, clave) => {
    const pedidos = Array.isArray(lista) ? lista.map(x => String(x).trim()).filter(Boolean) : [];
    const unicos = [...new Set(pedidos)];
    const buenos = unicos.filter(id => porId[id]);
    const malos = unicos.filter(id => !porId[id]);
    if (malos.length) {
      advertencias.push(
        '<<' + clave + '>> citó fuentes que no existen en la bibliografía de la unidad y se descartaron: ' +
          malos.join(', ')
      );
    }
    return buenos;
  };

  const delSyllabus = (clave, valor, ubicacion) => {
    asignar(clave, valor);
    traza.push({ marcador: '<<' + clave + '>>', origen: 'syllabus', ubicacion, fuentes_ids: [], sustento: null });
  };

  const generado = (clave, valor, opc) => {
    asignar(clave, valor);
    const ids = idsValidos(opc.fuentes, clave);
    if (opc.requiereFuente && ids.length === 0) {
      advertencias.push('<<' + clave + '>> no quedó respaldado por ninguna fuente de la bibliografía.');
    }
    ids.forEach(id => usos[id].push('<<' + clave + '>>'));
    traza.push({
      marcador: '<<' + clave + '>>',
      origen: 'generado',
      ubicacion: opc.ubicacion || null,
      fuentes_ids: ids,
      sustento: opc.sustento ? String(opc.sustento).trim() : null
    });
  };

  // ---- Información general ----
  delSyllabus('Pregrado', general.nivel_formacion, 'Información general > Nivel de formación');
  delSyllabus('Programa', general.programa, 'Información general > Programa');
  delSyllabus('Semestre', general.semestre, 'Información general > Semestre / periodo');
  delSyllabus('Asignatura', general.asignatura, 'Información general > Denominación');
  delSyllabus('Creditos', general.creditos, 'Información general > Nro. de Créditos');

  // Todos los resultados de aprendizaje de la asignatura (hay cursos con más de uno), cada uno en su línea.
  const todosRA = (base.resultados_aprendizaje || []).map(x => String(x).trim()).filter(Boolean);
  if (!todosRA.length) advertencias.push('El Syllabus no trae resultados de aprendizaje de la asignatura.');
  delSyllabus('Resultado_Aprendizaje', todosRA.join('\n'), 'Elementos del microcurrículo > Resultados de aprendizaje de la asignatura (' + todosRA.length + ')');

  delSyllabus(
    'Indicadores',
    (unidad.indicadores_logro || []).join('\n\n') || unidad.indicadores_logro_raw,
    'Unidad ' + N + ' > Indicadores de logro'
  );
  delSyllabus('Duracion', unidad.horas_estimadas, 'Unidad ' + N + ' > Horas estimadas de la unidad');
  delSyllabus('N', N, 'Unidad ' + N + ' > Número de unidad');
  delSyllabus('NombreUnidad', unidad.nombre, 'Unidad ' + N + ' > Nombre');
  const minusc = s => String(s || '').split(' ').map(w => (w.length > 1 && w === w.toUpperCase() && /[A-ZÁÉÍÓÚÑ]/.test(w) ? w : w.toLocaleLowerCase('es'))).join(' ');
  // Presentación de la unidad: un RED de introducción. La redacta el agente y dice qué se abordará en la unidad.
  const FRASE_PRESENTACION = 'Presentación de diapositivas de introducción';
  let presentacion = String(ia.presentacion_unidad || '').replace(/\s+/g, ' ').trim();
  if (!presentacion) {
    advertencias.push('El agente no devolvió la presentación de la unidad; se escribió solo con el nombre de la unidad.');
    presentacion = FRASE_PRESENTACION + ' sobre ' + minusc(limpiarNombre(unidad.nombre));
  } else if (!presentacion.startsWith(FRASE_PRESENTACION)) {
    advertencias.push('La presentación de la unidad no empezaba con "' + FRASE_PRESENTACION + '"; se antepuso.');
    presentacion = FRASE_PRESENTACION + ' sobre ' + minusc(limpiarNombre(unidad.nombre)) + '. ' + presentacion;
  }
  generado('Presentacion_Unidad', presentacion, {
    ubicacion: 'Unidad ' + N + ' > Presentación de la unidad',
    sustento: 'Redactada a partir del nombre, los temas, los subtemas y los indicadores de logro de la unidad.'
  });

  // ---- Desarrollo de la unidad ----
  delSyllabus('Nombre_Unidad', 'Unidad Nro. ' + N + ' — ' + unidad.nombre, 'Unidad ' + N + ' > Nombre');

  const desc = typeof ia.descripcion === 'string' ? { texto: ia.descripcion } : ia.descripcion || {};
  generado('Descripcion', desc.texto, {
    fuentes: desc.fuentes_ids,
    sustento: desc.sustento,
    ubicacion: 'Justificación de la asignatura + Unidad ' + N + ' (nombre e indicadores)',
    requiereFuente: true
  });
  // La plantilla escribe el marcador con tilde.
  m['<<Descripción>>'] = m['<<Descripcion>>'];


  const temasIa = Array.isArray(ia.temas) ? ia.temas : [];
  // Textos que van en negrita dentro de la celda de metodología de cada tema (los aplica «Separar subtemas en la tabla»).
  const negritaMet = {};
  const nombresTemas = unidad.temas.map(t => t.nombre);

  for (let t = 1; t <= 4; t++) {
    const temaSyl = unidad.temas[t - 1];
    const temaIa = temasIa[t - 1] || {};
    const recursos = Array.isArray(temaIa.recursos) ? temaIa.recursos : [];
    const ubTema = 'Unidad ' + N + ' > Tema ' + t;

    if (!temaSyl) advertencias.push('El Syllabus no trae un tema ' + t + ' para esta unidad.');
    if (recursos.length !== 6) {
      advertencias.push('El tema ' + t + ' devolvió ' + recursos.length + ' recursos en vez de 6.');
    }

    // Si la plantilla ya escribe el número ("1. <<Nombre_Tema1>>"), esa forma se reemplaza primero
    // para no duplicarlo; replaceAllText respeta el orden de los marcadores.
    const nombreTemaN = temaSyl ? temaNumerado(temaSyl.nombre, t) : '';
    m[t + '. <<Nombre_Tema' + t + '>>'] = nombreTemaN;
    // El encabezado de la plantilla ya dice "Tema 1:"; el nombre va sin número (la forma numerada se conserva para plantillas antiguas).
    const nombreTemaSolo = temaSyl ? limpiarNombre(String(temaSyl.nombre || '').replace(/^\s*\d+\s*[.)\-–]?\s*/, '')) : '';
    delSyllabus('Nombre_Tema' + t, nombreTemaSolo, ubTema + ' > Nombre');
    generado('N' + t, temaIa.semana, { ubicacion: ubTema + ' > Horas de los subtemas (reparto por semanas)' });
    // Metodología activa de aprendizaje: la que declara el Syllabus (nombre y descripción), en una celda combinada para los 3 subtemas.
    const metodologiasTema = (temaSyl && temaSyl.metodologias_tema) || [];
    const textoMet = metodologiasTema.map(x => (x.nombre ? x.nombre + (x.descripcion && x.descripcion !== x.nombre ? ': ' + x.descripcion : '') : x.descripcion)).join('\n\n');
    delSyllabus('Met_T' + t, textoMet, ubTema + ' > Estrategias de enseñanza > Metodología activa de aprendizaje (nombre y descripción)');
    negritaMet['<<Met_T' + t + '>>'] = metodologiasTema.filter(x => x.nombre).map(x => x.nombre + (x.descripcion && x.descripcion !== x.nombre ? ':' : ''));

    // Orden fijo de la plantilla: OVI 1, OVA 1, OVI 2, OVA 2, OVI 3, OVA 3.
    const orden = [['OVI', 1], ['OVA', 1], ['OVI', 2], ['OVA', 2], ['OVI', 3], ['OVA', 3]];

    // Subtemas que aborda cada recurso, según «Asignar actividades autoaprendizaje5».
    const cobertura = (temaSyl && temaSyl.cobertura_recursos) || {};
    const cubre = Object.fromEntries(['OVI1', 'OVA1', 'OVI2', 'OVA2', 'OVI3', 'OVA3'].map((clave, p) =>
      [clave, cobertura[clave] ? cobertura[clave].indices : [[0], [0], [1], [1], [2], [2]][p]]));
    // Cada subtema se desarrolla en dos recursos RED (OVI + OVA). La plantilla trae 6 filas por tema: alcanza para 3 subtemas.
    if (temaSyl) {
      (temaSyl.subtemas || []).forEach((_, i) => {
        const veces = Object.values(cubre).filter(ix => ix.includes(i)).length;
        if (veces < 2) advertencias.push('Tema ' + t + ': el subtema ' + (i + 1) + ' se desarrolla en ' + veces + ' recurso(s) y debe ir en dos. El tema tiene ' + temaSyl.subtemas.length + ' subtemas y la plantilla trae 6 filas por tema.');
      });
    }

    // Se usa para mostrar cada subtema una sola vez en la tabla.
    const subtemasMostrados = new Set();

    orden.forEach(([tipo, idx], posicion) => {
      const r = recursos[posicion] || {};
      if (r.tipo && (r.tipo !== tipo || r.indice !== idx)) {
        advertencias.push(
          'Tema ' + t + ', recurso ' + (posicion + 1) + ': se esperaba ' + tipo + ' ' + idx +
            ' y llegó ' + r.tipo + ' ' + r.indice + '.'
        );
      }
      const sufijo = '_' + tipo + '_' + idx + '_T' + t;
      const indices = cubre[tipo + idx] || [];
      const subs = temaSyl ? indices.map(i => temaSyl.subtemas[i]).filter(Boolean) : [];
      const sinNumero = s => String(s || '').replace(/^\s*\d+\s*[.)\-–]?\s*/, '');
      // Cada subtema lleva la numeración que le corresponde dentro de su tema (1., 2., 3.…).
      const textoSubtemas = temaSyl ? indices.filter(i => temaSyl.subtemas[i]).map(i => (i + 1) + '. ' + limpiarNombre(sinNumero(temaSyl.subtemas[i].nombre))).join('\n') : '';
      const claveSubtemas = norm(textoSubtemas);
      const ubSub = ubTema + ' > Subtema' + (indices.length > 1 ? 's ' : ' ') + indices.map(i => i + 1).join(' y ');

      // Metodología activa y técnica pedagógica de la fila: salen del Syllabus (la técnica decide el recurso y la actividad).
      const filaTec = (temaSyl && temaSyl.filas_tecnica && temaSyl.filas_tecnica[tipo + idx]) || {};
      const tecNombre = filaTec.tecnica ? limpiarNombre(filaTec.tecnica.nombre) : '';
      asignar('Tec' + sufijo, tecNombre);
      traza.push({
        marcador: '<<Tec' + sufijo + '>>',
        origen: filaTec.tecnica && filaTec.tecnica.origen === 'matriz RED' ? 'matriz RED (la técnica no figura en el Syllabus)' : 'syllabus',
        ubicacion: ubTema + ' > Estrategias de enseñanza > Técnicas pedagógicas', fuentes_ids: [], sustento: null
      });
      if (filaTec.tecnica && filaTec.tecnica.origen === 'matriz RED') tecnicasMatriz.add(tecNombre);

      const asignacionRed = temaSyl && temaSyl.recursos_red_asignados && temaSyl.recursos_red_asignados[tipo + idx];
      const formatoRed = String(asignacionRed && asignacionRed.red || '').trim();
      if (asignacionRed && asignacionRed.repetido_en_tema) repetidosTema.push('Tema ' + t + ': ' + formatoRed);

      if (!formatoRed) {
        advertencias.push('Tema ' + t + ', ' + tipo + ' ' + idx + ': no recibió un formato RED asignado desde el catálogo del anexo 3.10.');
      }

      // El marcador RED contiene únicamente el tipo de recurso asignado.
      asignar('Red' + sufijo, formatoRed);
      traza.push({
        marcador: '<<Red' + sufijo + '>>',
        origen: formatoRed ? 'catálogo RED, numeral 3.10' : 'sin asignación',
        ubicacion: ubSub,
        fuentes_ids: [],
        sustento: null
      });

      // Columna "Contenido del recurso": el nombre específico que desglosa el subtema.
      // Si el modelo antepuso el formato RED (p. ej. "Infografías estáticas: ..."), se quita.
      // Título del recurso: un nombre fluido del contenido. NO antepone el formato RED ni habla de la actividad
      // (SÍ: "Efectos de las prácticas físicas en el desempeño policial"; NO: "Mapa conceptual interactivo sobre los efectos…").
      const tituloFluido = (texto, formato) => {
        let s = String(texto || '').replace(/["“”«»]/g, '').replace(/\s+/g, ' ').trim();
        const original = s;
        const FORMATOS = '(?:infograf[ií]as?|l[ií]neas? de tiempo|diagramas? de flujo|mapas? conceptual(?:es)?|v[ií]deos?|podcasts?|presentaci[oó]n(?:es)?|acordeon(?:es)?|acorde[oó]n|galer[ií]as?|lecturas?|recursos?|actividad(?:es)?|estudios? de casos?|cuestionarios?|simulaci[oó]n(?:es)?|foros?|talleres?)';
        const ADJ = '(?:\\s+(?:est[aá]tic[oa]s?|interactiv[oa]s?|din[aá]mic[oa]s?|multimedia|acad[eé]mic[oa]s?|estructurad[oa]s?|explicativ[oa]s?|con audio|de micro-?learning|fundamental(?:es)?|diagramad[oa]s?|guiad[oa]s?|virtual(?:es)?|de casos?|autom[aá]tic[oa]s?))*';
        const COLA = '(?:\\s*[:\\-–—]\\s*|\\s+(?:sobre|acerca de|de|del|para|en|con)\\s+)';
        if (formato) s = s.replace(new RegExp('^\\s*' + formato.replace(/[.*+?^$()|[\]\\{}]/g, '\\$&') + '\\s*[:\\-–—]\\s*', 'i'), '');
        for (let i = 0; i < 2; i++) s = s.replace(new RegExp('^' + FORMATOS + ADJ + COLA, 'i'), '');
        s = limpiarNombre(s);
        return s.split(' ').length >= 3 ? s : limpiarNombre(original);
      };
      const nombreRecurso = tituloFluido(r.nombre, formatoRed);
      if (nombreRecurso && nombreRecurso !== limpiarNombre(r.nombre)) {
        advertencias.push('Tema ' + t + ', ' + tipo + ' ' + idx + ': se quitó el formato o la actividad del inicio del título ("' + limpiarNombre(r.nombre) + '").');
      }
      generado('Nom' + sufijo, nombreRecurso, {
        fuentes: r.fuentes_ids,
        sustento: r.sustento,
        ubicacion: ubSub,
        requiereFuente: true
      });

      // Muestra el subtema en la primera fila que lo usa.
      // Si ya apareció en otra fila, deja este marcador vacío para evitar duplicarlo.
      if (textoSubtemas && !subtemasMostrados.has(claveSubtemas)) {
        subtemasMostrados.add(claveSubtemas);
        delSyllabus('Rec' + sufijo, textoSubtemas, ubSub);
      } else {
        m['<<Rec' + sufijo + '>>'] = '';
        traza.push({
          marcador: '<<Rec' + sufijo + '>>',
          origen: textoSubtemas ? 'syllabus (repetición omitida)' : 'sin subtema',
          ubicacion: ubSub,
          fuentes_ids: [],
          sustento: null
        });
      }

      if (tipo === 'OVA') {
        const claveOva = 'OVA' + idx;
        const actividadAsignada = temaSyl && temaSyl.actividades_autoaprendizaje && temaSyl.actividades_autoaprendizaje[claveOva];
        if (!actividadAsignada) {
          advertencias.push('Tema ' + t + ', ' + claveOva + ': no tiene tipo RED asignado por el catálogo.');
        } else if (String(r.tipo_actividad || '').trim() !== actividadAsignada.red) {
          advertencias.push('Tema ' + t + ', ' + claveOva + ': el tipo devuelto no coincide con el tipo RED asignado (' + actividadAsignada.red + ').');
        }
        // La actividad lleva el tipo asignado más sobre qué trata, según el propósito y aplicación de la técnica del Syllabus.
        const nombreCatalogo = actividadAsignada ? actividadAsignada.red : limpiarNombre(r.tipo_actividad);
        const especifica = limpiarNombre(r.actividad);
        const palabrasAct = especifica ? especifica.split(/\s+/).length : 0;
        const minuscula = s => s ? s.charAt(0).toLocaleLowerCase('es') + s.slice(1) : s;
        let valorActividad = especifica;
        if (!especifica || palabrasAct < 4 || norm(especifica) === norm(nombreCatalogo)) {
          valorActividad = nombreCatalogo + (textoSubtemas ? ' sobre ' + minuscula(limpiarNombre(sinNumero((subs[0] && subs[0].nombre) || ''))) : '');
          advertencias.push('Tema ' + t + ', ' + claveOva + ': el modelo no especificó la actividad; se usó el tipo asignado con el subtema.');
        } else if (palabrasAct > 45) {
          advertencias.push('Tema ' + t + ', ' + claveOva + ': el nombre de la actividad tiene ' + palabrasAct + ' palabras; conviene acortarlo.');
        }
        const RAIZ = [[/simulaci|decision/, /simulaci|escenario|decision/], [/caso/, /caso/], [/foro/, /foro/], [/gamific/, /gamific|juego|reto/],
          [/cuestionario/, /cuestionario/], [/taller/, /taller/], [/tarea/, /tarea|producto|informe|entrega/], [/laboratorio/, /laboratorio/],
          [/clasific/, /clasific|categor/], [/emparej/, /relaci|empareja/], [/arrastre/, /arrastr|ordena|ubica/], [/crucigrama/, /crucigrama/]];
        const regla = RAIZ.find(([a]) => a.test(norm(nombreCatalogo)));
        if (regla && !regla[1].test(norm(valorActividad))) {
          advertencias.push('Tema ' + t + ', ' + claveOva + ': la actividad "' + valorActividad + '" no menciona el tipo asignado (' + nombreCatalogo + ').');
        }
        generado('Adu' + sufijo, valorActividad, {
          fuentes: r.fuentes_ids,
          sustento: r.sustento,
          ubicacion: ubSub + ' + propósito y aplicación de la técnica del Syllabus',
          requiereFuente: true
        });
        // Plantillas antiguas llamaban Nar_ a la actividad de los temas 2 a 4.
        m['<<Nar' + sufijo + '>>'] = m['<<Adu' + sufijo + '>>'];
      }

    });
  }

  // ---- Evaluaciones: Formativa 1, Formativa 2 y Sumativa ----
  // Estrategia, mecanismo e indicadores son literales del Syllabus; el modelo solo redacta el objetivo.
  // El momento de aplicación y los porcentajes los calcula el flujo.
  if (repetidosTema.length) advertencias.push('RED repetido dentro del tema porque las familias de las técnicas del Syllabus no tienen más formatos (' + repetidosTema.join('; ') + '). No se tomó ningún RED de otra familia.');
  if (tecnicasMatriz.size) advertencias.push('Técnicas tomadas de la matriz RED porque el Syllabus no las declara: ' + [...tecnicasMatriz].join('; ') + '.');
  const evaluaciones = Array.isArray(ia.evaluaciones) ? ia.evaluaciones : [];
  const asignadas = unidad.evaluaciones_asignadas || {};
  const plan = [(asignadas.formativas || [])[0], (asignadas.formativas || [])[1], asignadas.sumativa];
  if ((asignadas.formativas_en_syllabus || 0) !== 2) {
    advertencias.push('El Syllabus declara ' + (asignadas.formativas_en_syllabus || 0) + ' evaluación(es) formativa(s) y la plantilla trae 2 filas formativas.');
  }
  if (!asignadas.sumativa) advertencias.push('El Syllabus no declara una evaluación sumativa para esta unidad.');
  let suma = 0;
  plan.forEach((ev, k) => {
    const n = k + 1;
    const e = evaluaciones[k] || {};
    const ub = 'Unidad ' + N + ' > Estrategias evaluativas > ' + (n === 3 ? 'Evaluación sumativa' : 'Evaluación formativa ' + n);
    if (!ev) {
      ['Objetivo_', 'Estrategia_', 'Mecanismo_', 'Momento_', 'Porcentaje_'].forEach(p => { m['<<' + p + n + '>>'] = ''; });
      return;
    }
    generado('Objetivo_' + n, e.objetivo, { fuentes: e.fuentes_ids, ubicacion: ub + ' + Indicadores de logro' });
    const ind = (ev.indicadores || []).length ? '. Indicadores: (' + ev.indicadores.join(', ') + ')' : '';
    delSyllabus('Estrategia_' + n, limpiarNombre(ev.estrategia) + ind, ub + ' > Estrategia');
    if (ind) negritaMet['<<Estrategia_' + n + '>>'] = ['Indicadores: (' + ev.indicadores.join(', ') + ')'];
    delSyllabus('Mecanismo_' + n, limpiarNombre(ev.mecanismo), ub + ' > Mecanismo');
    const momento = n === 3
      ? 'Al finalizar todos los temas'
      : 'Después de abordar los siguientes temas:\n' + (ev.temas || []).map(x => temaNumerado(x.nombre, x.numero)).join('\n');
    delSyllabus('Momento_' + n, momento, 'Unidad ' + N + ' > Temas cubiertos (formativas: mitades de la unidad; sumativa: al final)');
    delSyllabus('Porcentaje_' + n, ev.porcentaje, 'Ponderación: 60 % entre las formativas y 40 % la sumativa (el Syllabus no trae porcentajes)');
    suma += parseFloat(String(ev.porcentaje || '').replace(',', '.')) || 0;
  });
  if (Math.round(suma) !== 100) {
    advertencias.push('Los porcentajes de evaluación suman ' + suma + '% y deberían sumar 100%.');
  }

  // ---- registro de fuentes ----
  const bibliografiaRegistro = entradas.map(e => ({ ...e, citada_en: usos[e.id] }));
  const noCitadas = entradas.filter(e => usos[e.id].length === 0).map(e => e.id);

  const md = [];
  md.push('# Registro de fuentes — Unidad ' + N + ': ' + unidad.nombre);
  md.push('');
  md.push('- **Asignatura:** ' + general.asignatura + ' (' + (general.programa || 's. d.') + ')');
  md.push('- **Syllabus:** ' + (base.archivo || 's. d.') + (base.origen && base.origen.url ? ' — ' + base.origen.url : ''));
  md.push('- **Actualización del Syllabus:** ' + (general.fecha_actualizacion || 's. d.'));
  md.push('- **Nivel de verificación:** ' + NIVEL_VERIFICACION);
  md.push('');
  md.push('## Bibliografía de la unidad');
  bibliografiaRegistro.forEach(e => {
    const donde = e.citada_en.length ? e.citada_en.join(', ') : 'NO CITADA en ningún recurso';
    md.push('- **[' + e.id + ']** ' + e.texto + '  \n  Citada en: ' + donde);
  });
  md.push('');
  md.push('## Trazabilidad por marcador');
  md.push('| Marcador | Origen | Ubicación en el Syllabus | Fuentes | Sustento |');
  md.push('|---|---|---|---|---|');
  traza.forEach(t => {
    md.push(
      '| `' + t.marcador + '` | ' + t.origen + ' | ' + (t.ubicacion || '') + ' | ' +
        (t.fuentes_ids.join(', ') || '—') + ' | ' + (t.sustento || '').replace(/\|/g, '/') + ' |'
    );
  });
  if (advertencias.length) {
    md.push('');
    md.push('## Advertencias');
    advertencias.forEach(a => md.push('- ' + a));
  }

  const totalMarcadores = Object.keys(m).length;

  return {
    json: {
      archivo: base.archivo,
      origen: base.origen,
      asignatura: general.asignatura,
      unidad: N,
      nombre_unidad: unidad.nombre,
      total_unidades: base.total_unidades,
      control_formatos_red: unidad.control_formatos_red || {
        max_videos_por_unidad: 1,
        videos_asignados: videosAsignados.length,
        distribucion: {}
      },
      actividades_autoaprendizaje_asignadas: unidad.temas.map(t => ({
        tema: t.nombre,
        OVA1: t.actividades_autoaprendizaje && t.actividades_autoaprendizaje.OVA1 && t.actividades_autoaprendizaje.OVA1.red,
        OVA2: t.actividades_autoaprendizaje && t.actividades_autoaprendizaje.OVA2 && t.actividades_autoaprendizaje.OVA2.red,
        OVA3: t.actividades_autoaprendizaje && t.actividades_autoaprendizaje.OVA3 && t.actividades_autoaprendizaje.OVA3.red
      })),
      formatos_red_asignados: unidad.temas.map(t => ({
        tema: t.nombre,
        OVI1: t.recursos_red_asignados && t.recursos_red_asignados.OVI1 && t.recursos_red_asignados.OVI1.red,
        OVA1: t.recursos_red_asignados && t.recursos_red_asignados.OVA1 && t.recursos_red_asignados.OVA1.red,
        OVI2: t.recursos_red_asignados && t.recursos_red_asignados.OVI2 && t.recursos_red_asignados.OVI2.red,
        OVA2: t.recursos_red_asignados && t.recursos_red_asignados.OVA2 && t.recursos_red_asignados.OVA2.red,
        OVI3: t.recursos_red_asignados && t.recursos_red_asignados.OVI3 && t.recursos_red_asignados.OVI3.red,
        OVA3: t.recursos_red_asignados && t.recursos_red_asignados.OVA3 && t.recursos_red_asignados.OVA3.red
      })),
      marcadores: m,
      indicadores_logro: unidad.indicadores_logro || [],
      metodologias_negrita: negritaMet,
      bibliografia: {
        basica: unidad.bibliografia.basica.entradas,
        complementaria: unidad.bibliografia.complementaria.entradas,
        basica_raw: unidad.bibliografia.basica.raw,
