const PLANTILLA_POR_DEFECTO =
  'https://docs.google.com/document/d/1Pvf3ImiHssKrknCdRf84Zt_3pcIlJ-mkoRvdxVsx_4Y/edit';

const peticion = $('Webhook Syllabus1').first().json;
