  (peticion.body && peticion.body.plantilla_url) ||
    (peticion.query && peticion.query.plantilla_url) ||
    PLANTILLA_POR_DEFECTO
).trim();

const m = /docs\.google\.com\/document\/d\/([A-Za-z0-9_-]+)/.exec(url);

if (!m) {
  throw new Error(
    '"plantilla_url" no es un Google Doc ("docs.google.com/document/d/<ID>"): ' + url
  );
}

return [
  {
    json: {
      plantilla_url: url,
      plantilla_id: m[1],
      plantilla_export_url:
        'https://docs.google.com/document/d/' + m[1] + '/export?format=docx'
    }
  }
];

// Nodo Code: "Preparar plantilla"
// Igual que "Preparar DOCX", pero para la plantilla. Si la descarga falló o el
// documento es privado, no corta el flujo: deja constancia y el cotejo se omite.

const item = $input.first();

if (!item.binary || !item.binary.data) {
  return [{ json: { ...item.json, plantilla_error: 'No se pudo descargar la plantilla.' } }];
}

const cabecera = Buffer.from(await this.helpers.getBinaryDataBuffer(0, 'data')).slice(0, 2).toString('latin1');
if (cabecera !== 'PK') {
  return [
    {
      json: {
        ...item.json,
        plantilla_error:
          'Google no devolvió un .docx: la plantilla no está compartida con "Cualquier persona con el enlace".'
      }
    }
  ];
}

item.binary.data.fileName = 'plantilla.zip';
item.binary.data.fileExtension = 'zip';
item.binary.data.mimeType = 'application/zip';

return [item];

// Nodo Code: "Cotejar plantilla"
// Lee los marcadores REALES de la plantilla de Google Docs y los compara con los
// que generó el flujo. Así la salida siempre cuadra con la plantilla vigente y
// cualquier desajuste queda a la vista en lugar de descubrirse al rellenar.

function unescapeXml(s) {
  return s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
}

const armados = $('Armar salida1').all();
const entrada = $input.first();
const urlPlantilla = (() => {
  try { return $('Resolver plantilla1').first().json.plantilla_url; } catch (e) { return null; }
})();

const binarios = entrada.binary || {};
const claves = Object.keys(binarios);
const ruta = k => [binarios[k].directory, binarios[k].fileName, k].filter(Boolean).join('/');
const clave =
  claves.find(k => /word[\/\\]document\.xml$/i.test(ruta(k))) ||
  claves.find(k => /document\.xml$/i.test(binarios[k].fileName || k));

// Sin plantilla disponible: se devuelve lo generado tal cual, con el motivo.
if (!clave) {
  const motivo = (entrada.json && (entrada.json.plantilla_error || entrada.json.error)) || 'Plantilla no disponible.';
  return armados.map(a => ({
    json: {
      ...a.json,
      plantilla: { estado: 'no_cotejada', url: urlPlantilla, motivo: String(motivo.message || motivo) }
    }
  }));
}

const xml = (await this.helpers.getBinaryDataBuffer(0, clave)).toString('utf8');
const texto = unescapeXml(
  (xml.match(/<w:t(?: [^>]*)?>[\s\S]*?<\/w:t>/g) || []).map(t => t.replace(/<[^>]+>/g, '')).join('')
);
const enPlantilla = [...new Set(texto.match(/<<[^<>]+>>/g) || [])];

return armados.map(a => {
  const j = a.json;
  const marcadores = { ...j.marcadores };


  const sinValor = enPlantilla.filter(k => !marcadores[k]);
  const sinUso = Object.keys(marcadores).filter(k => !enPlantilla.includes(k));

  const advertencias = [...j.advertencias];
  if (sinValor.length) {
    advertencias.push(
      'La plantilla tiene ' + sinValor.length + ' marcador(es) que el flujo no llena: ' + sinValor.join(', ') +
        '. Si son de "Temporización", la plantilla de Drive está desactualizada.'
    );
  }

  return {
    json: {
      ...j,
      marcadores,
      advertencias,
      plantilla: {
        estado: 'cotejada',
        url: urlPlantilla,
        total_marcadores: enPlantilla.length,
        sin_valor: sinValor,
        sin_uso: sinUso
      }
    }
  };
});

