        }
      }
      contadorFilas += tecnicasRed.length ? saltos + 1 : 1;
      if (!candidatos.length) candidatos = disponibles;
      if (!candidatos.length) throw new Error('No hay RED disponible para unidad ' + unidad.numero + ', tema ' + (temaIndex + 1) + ', ' + slot.clave);
      const sinFamiliaRepetida = candidatos.filter(c => !familiasTema.has(familia(c.red)));
      if (sinFamiliaRepetida.length) candidatos = sinFamiliaRepetida;
      // Cubrir primero los formatos menos usados; respetar la prioridad del nivel y, en igualdad, la pertinencia del subtema.
      const menosUsos = Math.min(...candidatos.map(c => usoPorFormato.get(c.red) || 0));
      candidatos = candidatos.filter(c => (usoPorFormato.get(c.red) || 0) === menosUsos);
      const mejorPrioridad = Math.min(...candidatos.map(c => PRIORIDAD[c.prioridad[nivel]] ?? 3));
      candidatos = candidatos.filter(c => (PRIORIDAD[c.prioridad[nivel]] ?? 3) === mejorPrioridad);
      const maxAfinidad = Math.max(...candidatos.map(c => afinidadRed(c.red, slot.texto, slot.tipo)));
      candidatos = candidatos.filter(c => afinidadRed(c.red, slot.texto, slot.tipo) === maxAfinidad);
      const sinRepetir = candidatos.filter(c => c.red !== anterior);
      if (sinRepetir.length) candidatos = sinRepetir;
      const elegido = barajar(candidatos, rnd)[0];
      usadosTema.add(elegido.red);
      familiasTema.add(familia(elegido.red));
      usoPorFormato.set(elegido.red, (usoPorFormato.get(elegido.red) || 0) + 1);
      if (ES_VIDEO(elegido)) videosUsados++;
      if (ES_PODCAST(elegido)) podcastsUsados++;
      anterior = elegido.red;
      // Técnica de la fila: la del Syllabus cuya categoría contiene el formato; si ninguna, la familia de la matriz RED.
      const kind = tipoDeRed(elegido.red);
      const delSyllabus = (tecnicaElegida && (CATEGORIAS_DE_TECNICA[tecnicaElegida.tipo] || []).includes(kind) ? tecnicaElegida : null)
        || tecnicas.find(x => (CATEGORIAS_DE_TECNICA[x.tipo] || []).includes(kind)) || null;
      tecnicaPorFila[temaIndex][slot.clave] = delSyllabus
        ? { nombre: delSyllabus.nombre, proposito: delSyllabus.proposito, tipo: delSyllabus.tipo, origen: 'Syllabus' }
        : { nombre: FAMILIAS[kind], proposito: '', tipo: kind, origen: 'matriz RED' };
      asignaciones[temaIndex][slot.clave] = {
        ...elegido,
        repetido_en_tema: repetido,
        prioridad_aplicada: elegido.prioridad[nivel],
        nivel_aplicado: nivel,
        ciclo: 1 + (usoPorFormato.get(elegido.red) - 1),
        limite_video_por_unidad: MAX_VIDEOS_UNIDAD
      };
    }
  }
  if (videosUsados > MAX_VIDEOS_UNIDAD) throw new Error('Regla violada: mas de un video en unidad '+unidad.numero);
  if (podcastsUsados > MAX_PODCASTS_UNIDAD) throw new Error('Regla violada: mas de un podcast en unidad '+unidad.numero);
  // Actividades de autoaprendizaje: salen del listado de actividades del nivel (Prioritarias y Complementarias).
  // Primero la que corresponde a la técnica de la fila (estudio de casos, simulación, foro…); luego las demás técnicas del
  // Syllabus; por último, el listado del nivel por prioridad.
  const prioridadAct = a => PRIORIDAD[a.prioridad[nivel]] ?? 3;
  const relleno = [];
  for (const prio of ['Prioritaria', 'Complementaria', 'Ocasional']) relleno.push(...barajar(CATALOGO.filter(c => c.prioridad[nivel] === prio), rnd));
  relleno.sort((a, b) => (tipoDeActividad(a.red) === 'practica' ? 0 : 1) - (tipoDeActividad(b.red) === 'practica' ? 0 : 1) || prioridadAct(a) - prioridadAct(b));
  const actividadesTema = temas.map((tema, i) => {
    const tecnicas = tecnicasDe(tema);
    const delSyllabus = [];
    for (const t of tecnicas) {
      if (!KINDS_ACTIVIDAD.has(t.tipo)) continue;
      const a = actividadParaTecnica(t);
      if (a && a.prioridad[nivel] !== 'Ocasional' && !delSyllabus.some(x => x.red === a.red)) delSyllabus.push({ ...a, tecnica_origen: t.nombre });
    }
    const usadas = new Set();
    const lista = [];
    for (const clave of ['OVA1', 'OVA2', 'OVA3']) {
      const tecnicaFila = (tecnicaPorFila[i][clave] || {}).nombre;
      let a = delSyllabus.find(x => x.tecnica_origen === tecnicaFila && !usadas.has(x.red))
        || delSyllabus.find(x => !usadas.has(x.red))
        || relleno.find(x => !usadas.has(x.red));
      usadas.add(a.red);
      lista.push(a.tecnica_origen === undefined ? { ...a, tecnica_origen: null } : a);
    }
    return lista;
  });

  // Técnica de cada fila de la tabla (OVI 1, OVA 1, … OVA 3); la metodología activa va una sola vez por tema.
  const filasTecnica = i => Object.fromEntries(ORDEN.map(([clave]) => [clave, { tecnica: tecnicaPorFila[i][clave] }]));

  // Evaluaciones: las dos formativas se reparten los temas y los indicadores por mitades (1-2 y 3-4); la sumativa evalúa todo.
  // Porcentajes: 30 % cada formativa y 40 % la sumativa. Estrategia y mecanismo salen literales del Syllabus.
  const evSyl = unidad.evaluacion_syllabus || { formativas: [], sumativas: [] };
  const formativasUsadas = evSyl.formativas.slice(0, 2);
  const mitad = Math.ceil(temas.length / 2);
  const rango = (a, b) => temas.map((t, i) => ({ numero: i + 1, nombre: t.nombre })).slice(a, b);
  const grupos = formativasUsadas.length <= 1 ? [rango(0, temas.length)] : [rango(0, mitad), rango(mitad, temas.length)];
  const numsInd = (unidad.indicadores_logro || []).map((x, i) => { const m = /Indicador de Logro\s*(\d+)/i.exec(x); return m ? Number(m[1]) : i + 1; });
  const fmtInd = n => 'Ind-' + String(n).padStart(2, '0');
  const mitadInd = Math.ceil(numsInd.length / 2);
  const indDe = k => (formativasUsadas.length <= 1 ? numsInd : (k === 0 ? numsInd.slice(0, mitadInd) : numsInd.slice(mitadInd))).map(fmtInd);
  const evaluaciones_asignadas = {
    formativas: formativasUsadas.map((f, k) => ({
      numero: k + 1, ...f, indicadores_syllabus: f.indicadores, indicadores: indDe(k), temas: grupos[k], porcentaje: '30%'
    })),
    sumativa: evSyl.sumativas[0] ? { ...evSyl.sumativas[0], indicadores_syllabus: evSyl.sumativas[0].indicadores, indicadores: numsInd.map(fmtInd), temas: rango(0, temas.length), porcentaje: '40%' } : null,
    formativas_en_syllabus: evSyl.formativas.length
  };
  const temasPlan = temas.map((tema, i) => ({
    ...tema,
    // Qué subtema(s) aborda cada recurso; lo usan el prompt y «Armar salida2».
    cobertura_recursos: Object.fromEntries(ORDEN.map(([clave], posicion) => {
      const indices = coberturaRecursos((tema.subtemas || []).length)[posicion];
      return [clave, { indices, subtemas: indices.map(k => nombreSubtema((tema.subtemas || [])[k])) }];
    })),
    recursos_red_asignados: asignaciones[i],
    actividades_autoaprendizaje: {
      OVA1: { ...actividadesTema[i][0], nivel_aplicado: nivel },
      OVA2: { ...actividadesTema[i][1], nivel_aplicado: nivel },
      OVA3: { ...actividadesTema[i][2], nivel_aplicado: nivel }
    },
    metodologias_tema: ensenanzaDe(tema).metodologias || [],
    filas_tecnica: filasTecnica(i)
  }));
  return {
    json: {
      ...j,
      nivel_actividades: nivel,
      unidad: {
        ...unidad,
        temas: temasPlan,
        evaluaciones_asignadas,
        control_formatos_red: {
          max_videos_por_unidad: MAX_VIDEOS_UNIDAD,
          videos_asignados: videosUsados,
          max_podcasts_por_unidad: MAX_PODCASTS_UNIDAD,
          podcasts_asignados: podcastsUsados,
          distribucion: Object.fromEntries(usoPorFormato)
        }
      }
    },
    pairedItem: { item: itemIndex }
  };
});

parameters.inputSchema:
{
  "type": "object",
  "required": [
    "descripcion",
    "temas",
    "evaluaciones",
    "presentacion_unidad"
  ],
  "additionalProperties": false,
  "properties": {
    "descripcion": {
      "type": "object",
      "required": [
        "texto",
        "fuentes_ids",
        "sustento"
      ],
      "additionalProperties": false,
      "properties": {
        "texto": {
          "type": "string",
          "description": "Descripción de la unidad, de 3 a 5 frases."
        },
        "fuentes_ids": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "IDs de la bibliografía recibida (p. ej. U1-B2) en los que se apoya la descripción."
        },
        "sustento": {
          "type": "string",
          "description": "Una frase que explica el vínculo entre la descripción y las fuentes citadas, según sus títulos."
        }
      }
    },
    "resultado_aprendizaje": {
      "type": "string",
      "description": "Cadena vacía: el sistema escribe todos los resultados de aprendizaje de la asignatura."
    },
    "temas": {
      "type": "array",
      "minItems": 4,
      "maxItems": 4,
      "items": {
        "type": "object",
        "required": [
          "numero",
          "semana",
          "recursos"
        ],
        "additionalProperties": false,
        "properties": {
          "numero": {
            "type": "integer",
            "minimum": 1,
            "maximum": 4
          },
          "semana": {
            "type": "string",
            "description": "Semana o rango de semanas del tema dentro de la unidad, por ejemplo 1 o 2-3."
          },
          "recursos": {
            "type": "array",
            "minItems": 6,
            "maxItems": 6,
            "description": "Siempre en el orden OVI 1, OVA 1, OVI 2, OVA 2, OVI 3, OVA 3.",
            "items": {
              "type": "object",
              "required": [
                "tipo",
                "indice",
                "nombre",
                "actividad",
                "fuentes_ids",
                "sustento",
                "tipo_actividad"
              ],
              "additionalProperties": false,
              "properties": {
                "tipo": {
                  "type": "string",
                  "enum": [
                    "OVI",
                    "OVA"
                  ]
                },
                "indice": {
                  "type": "integer",
                  "minimum": 1,
                  "maximum": 3
                },
                "nombre": {
                  "type": "string",
                  "description": "Título de 4 a 10 palabras de lo que aborda este recurso; va en la columna \"Título del recurso\". Los recursos del mismo subtema tratan aspectos distintos de él. Sin el formato RED."
                },
                "actividad": {
                  "type": "string",
                  "description": "Solo OVA: nombre específico y explícito de la actividad (tipo asignado + sobre qué trata, 8 a 30 palabras, una frase sin punto final, según el propósito y aplicación de la técnica de su fila). En los OVI, cadena vacía."
                },
                "fuentes_ids": {
                  "type": "array",
                  "minItems": 1,
                  "items": {
                    "type": "string"
                  },
                  "description": "IDs de la bibliografía recibida (p. ej. U1-B2, U1-C1) que respaldan este recurso. Al menos uno."
                },
                "sustento": {
                  "type": "string",
                  "description": "Una frase que explica por qué esas fuentes corresponden al subtema, según sus títulos."
                },
                "tipo_actividad": {
                  "type": "string",
                  "description": "En OVA, nombre exacto del tipo de actividad de autoaprendizaje asignado; no es el formato RED. En OVI, cadena vacía."
                }
              }
            }
          }
        }
      }
    },
    "evaluaciones": {
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "description": "Formativa 1, Formativa 2 y Sumativa, en ese orden.",
      "items": {
        "type": "object",
        "required": [
          "tipo",
          "objetivo",
          "fuentes_ids"
        ],
        "additionalProperties": false,
        "properties": {
          "tipo": {
            "type": "string",
            "enum": [
              "Formativa",
              "Sumativa"
            ]
          },
          "objetivo": {
            "type": "string",
            "description": "Objetivo de evaluación en infinitivo, observable y específico; indica la evidencia o producto concreto, fiel a la estrategia, el mecanismo y los indicadores del Syllabus, limitado a los temas que cubre esa evaluación."
          },
          "fuentes_ids": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "IDs de la bibliografía recibida que respaldan la evaluación; puede ir vacío si se basa solo en los indicadores de logro."
          }
        }
      }
    },
    "presentacion_unidad": {
      "type": "string",
      "description": "Presentación de la unidad (RED de introducción): empieza con \"Presentación de diapositivas de introducción a la [ordinal] unidad, donde conoceremos…\" y luego \"Abordaremos…\" con los temas y subtemas; 50 a 110 palabras, una sola línea."
    }
  }
}
